import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) ʿulūm al-Qurʾān: naskh and the debates around it, iʿjāz, asbāb al-nuzūl, Makkan and Madinan, chronology, muḥkam and mutashābih, divisions and counts, classical works. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "xul-001", s: "ulum", g: 4, d: 6, t: ["naskh", "types-of-naskh"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, naw‘ 47 (al-nāsikh wa-l-mansūkh); al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān",
    en: ["Which classification of naskh in the Quran is given by the scholars of the Quranic sciences?", ["Abrogation of the ruling while the wording remains; of the wording while the ruling remains; and of both the wording and the ruling", "Abrogation of the Quran by earlier scriptures, by the Sunna, and by consensus alone", "Abrogation of a verse by an interpretation, by a reading, or by a sūra", "Abrogation only of the wording, since the rulings are never abrogated"], "The books list three kinds: naskh al-ḥukm dūn al-tilāwa (the most common, as in the verse about the year’s waiting of widows), naskh al-tilāwa dūn al-ḥukm (as in the verse of stoning mentioned in ʿUmar’s statement, whose wording was lifted but the ruling stands), and naskh al-ḥukm wa-l-tilāwa together, for which reports are cited. The existence and the extent of each kind is discussed by the scholars."],
    de: ["Welche Einteilung des Naskh im Koran geben die Gelehrten der Koranwissenschaften?", ["Aufhebung des Urteils bei bleibendem Wortlaut; des Wortlauts bei bleibendem Urteil; und von beidem zugleich", "Aufhebung des Korans durch frühere Schriften, durch die Sunna und allein durch Konsens", "Aufhebung eines Verses durch eine Deutung, eine Lesart oder eine Sure", "Aufhebung nur des Wortlauts, da die Urteile nie aufgehoben werden"], "Die Bücher nennen drei Arten: naskh al-ḥukm dūn at-tilāwa (die häufigste, wie beim Vers über die einjährige Wartezeit der Witwen), naskh at-tilāwa dūn al-ḥukm (wie beim Steinigungsvers, auf den ʿUmars Aussage verweist: Der Wortlaut wurde aufgehoben, das Urteil besteht) und naskh al-ḥukm wa-t-tilāwa zusammen, wofür Berichte angeführt werden. Das Vorkommen und der Umfang jeder Art werden von den Gelehrten diskutiert."],
    ar: ["ما تقسيم النسخ في القرآن عند علماء علوم القرآن؟", ["نسخ الحكم مع بقاء التلاوة، ونسخ التلاوة مع بقاء الحكم، ونسخ الحكم والتلاوة معًا", "نسخ القرآن بالكتب السابقة وبالسنة وبالإجماع فقط", "نسخ الآية بالتأويل أو بالقراءة أو بالسورة", "نسخ التلاوة فقط لأن الأحكام لا تُنسخ"], "يذكرون ثلاثة أنواع: نسخ الحكم دون التلاوة (وهو الأكثر كآية العدة سنة)، ونسخ التلاوة دون الحكم (كآية الرجم التي في كلام عمر رُفعت تلاوتها وبقي حكمها)، ونسخ الحكم والتلاوة معًا وتُذكر له روايات، ويبحث العلماء في وجود كل نوع وسعته."] },

  { id: "xul-002", s: "ulum", g: 4, d: 6, t: ["naskh", "examples"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr (on 2:240); al-Ṭabarī, Jāmiʿ al-Bayān; al-Suyūṭī, al-Itqān", v: "2:240", w: 10,
    en: ["The verse shown prescribes a year for widows, with provision and the right to stay. By which verse is it commonly said to be abrogated?", ["2:234, which sets four months and ten days for widows", "2:228, which sets three monthly courses for divorced women", "65:4, which sets three months for women who no longer have courses", "4:12, which gives shares of inheritance"], "A well-known report in al-Bukhārī has Ibn al-Zubayr asking ʿUthmān why he included this verse, as it had been abrogated by the other; the answer was that he would not change anything from its place. Most commentators say the waiting period was reduced to four months and ten days. Some, like Mujāhid, held that the right to residence remained."],
    de: ["Der gezeigte Vers schreibt für Witwen ein Jahr vor, mit Versorgung und Wohnrecht. Durch welchen Vers soll er allgemein aufgehoben sein?", ["2:234, der für Witwen vier Monate und zehn Tage festsetzt", "2:228, der drei Monatsblutungen für Geschiedene festsetzt", "65:4, der drei Monate für Frauen ohne Blutungen festsetzt", "4:12, der Erbanteile vergibt"], "Ein bekannter Bericht bei al-Buḫārī lässt Ibn az-Zubair ʿUṯmān fragen, warum er diesen Vers aufnehme, da er durch den anderen aufgehoben sei; die Antwort lautete, er werde nichts von seiner Stelle ändern. Die meisten Kommentatoren sagen, die Wartezeit sei auf vier Monate und zehn Tage verkürzt worden. Manche, wie Muǧāhid, meinten, das Wohnrecht bleibe bestehen."],
    ar: ["الآية المعروضة توجب للأرملة سنة نفقة وسكنى. بأي آية يقال في المشهور إنها منسوخة؟", ["البقرة 234 التي تحدد أربعة أشهر وعشرًا", "البقرة 228 التي تحدد ثلاثة قروء للمطلقات", "الطلاق 4 التي تحدد ثلاثة أشهر لمن لا تحيض", "النساء 12 التي توزع الأنصبة"], "في صحيح البخاري أن ابن الزبير سأل عثمان لماذا تكتب هذه الآية وقد نسختها الأخرى، فقال إنه لا يغيّر شيئًا من مكانه. ويقول أكثر المفسرين إن العدة نُقصت إلى أربعة أشهر وعشر، وذهب مجاهد وغيره إلى بقاء حق السكنى."] },

  { id: "xul-003", s: "ulum", g: 4, d: 6, t: ["naskh", "examples"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr (on 8:65–66); al-Ṭabarī, Jāmiʿ al-Bayān", v: "8:65", w: 13,
    en: ["The verse shown sets the ratio of twenty believers to two hundred unbelievers. What follows in the next verse, according to Ibn ʿAbbās?", ["A reduction of the ratio, so that a hundred patient believers should face two hundred", "An increase to a hundred against one", "A cancellation of the duty of fighting", "A prohibition of fighting in all circumstances"], "A report in al-Bukhārī from Ibn ʿAbbās says that the command to stand against ten times as many was lightened by God, who knew their weakness, to two times. The reduction is commonly cited as an example of naskh al-ḥukm in the Quran, though some scholars speak of takhfīf (alleviation) rather than abrogation."],
    de: ["Der gezeigte Vers setzt das Verhältnis von zwanzig Gläubigen zu zweihundert Ungläubigen fest. Was folgt im nächsten Vers nach Ibn ʿAbbās?", ["Eine Herabsetzung des Verhältnisses, sodass hundert standhafte Gläubige zweihundert gegenüberstehen sollen", "Eine Erhöhung auf hundert gegen einen", "Eine Aufhebung der Kampfpflicht", "Ein Verbot des Kampfes unter allen Umständen"], "Ein Bericht bei al-Buḫārī von Ibn ʿAbbās besagt, der Befehl, zehnfacher Übermacht standzuhalten, sei von Gott, der ihre Schwäche kannte, auf das Zweifache erleichtert worden. Die Herabsetzung wird gewöhnlich als Beispiel für naskh al-ḥukm im Koran angeführt, wobei manche Gelehrte eher von Taḫfīf (Erleichterung) als von Aufhebung sprechen."],
    ar: ["تضع الآية المعروضة نسبة عشرين من المؤمنين إلى مئتين من الكفار. ماذا يعقبها في الآية التالية بحسب ابن عباس؟", ["تخفيف النسبة فيثبت مئة صابرة أمام مئتين", "زيادة النسبة إلى مئة مقابل واحد", "إلغاء فرض القتال", "تحريم القتال في كل الأحوال"], "روى البخاري عن ابن عباس أن أمر مصابرة عشرة أمثالهم خفّفه الله لما علم ضعفهم إلى المثلين، ويُذكر ذلك مثالًا على نسخ الحكم في القرآن، وإن عبّر بعض العلماء عن ذلك بالتخفيف لا النسخ."] },

  { id: "xul-004", s: "ulum", g: 4, d: 7, t: ["naskh", "disagreement"], tr: ["comparative"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr and Kitāb al-Ṣawm; Muslim, Ṣaḥīḥ, Kitāb al-Ṣiyām (hadith of Salama ibn al-Akwaʿ); al-Ṭabarī, Jāmiʿ al-Bayān", v: "2:184", w: 16,
    en: ["The verse shown mentions a fidya for ‘those who are able to fast’. What is the disagreement, as recorded in the reports?", ["Salama ibn al-Akwaʿ reported that the option to pay fidya instead of fasting was abrogated by the next verse, whereas Ibn ʿAbbās said the verse is not abrogated and applies to the old who cannot fast", "All Companions agreed that the verse was fully abrogated", "All Companions agreed that the verse remains for everyone", "Ibn ʿAbbās held it abrogated and Salama held it permanent"], "In the account of Salama, when the verse was revealed, whoever wished could break the fast and feed a poor person until the following verse abrogated it. Ibn ʿAbbās, in al-Bukhārī, said that it was not abrogated but is for the old man and woman who are unable to fast. Both are reported in the Ṣaḥīḥ collections, and the jurists usually combine them by holding that the fidya remains for the permanently unable."],
    de: ["Der gezeigte Vers nennt eine Fidya für ‚die, die fasten können‘. Was ist die Meinungsverschiedenheit nach den Berichten?", ["Salama ibn al-Akwaʿ berichtete, die Möglichkeit der Fidya statt des Fastens sei durch den nächsten Vers aufgehoben worden, während Ibn ʿAbbās sagte, der Vers sei nicht aufgehoben und gelte für Alte, die nicht fasten können", "Alle Gefährten waren sich einig, der Vers sei ganz aufgehoben", "Alle Gefährten waren sich einig, der Vers gelte weiter für alle", "Ibn ʿAbbās hielt ihn für aufgehoben und Salama für dauerhaft"], "Nach dem Bericht Salamas durfte, als der Vers offenbart wurde, wer wollte, das Fasten brechen und einen Armen speisen, bis der folgende Vers dies aufhob. Ibn ʿAbbās sagte bei al-Buḫārī, er sei nicht aufgehoben, sondern gelte für den alten Mann und die alte Frau, die nicht fasten können. Beides steht in den Ṣaḥīḥ-Sammlungen, und die Juristen verbinden sie gewöhnlich, indem sie die Fidya für dauerhaft Unfähige bestehen lassen."],
    ar: ["الآية المعروضة تذكر فدية للقادرين على الصوم. ما الخلاف كما في الروايات؟", ["روى سلمة بن الأكوع أن التخيير بين الصوم والفدية نُسخ بالآية التالية، وقال ابن عباس إن الآية غير منسوخة وهي للشيخ الكبير العاجز عن الصوم", "اتفق الصحابة على أن الآية منسوخة بالكلية", "اتفق الصحابة على أن الآية باقية للجميع", "قال ابن عباس بنسخها وقال سلمة ببقائها"], "في رواية سلمة أنه لما نزلت كان من شاء صام ومن شاء أفطر وأطعم مسكينًا حتى نسختها الآية التي بعدها، وروى البخاري عن ابن عباس أنها ليست منسوخة وهي للشيخ الكبير والمرأة الكبيرة لا يستطيعان الصوم، والروايتان في الصحيحين، ويجمع الفقهاء بينهما ببقاء الفدية للعاجز عجزًا دائمًا."] },

  { id: "xul-005", s: "ulum", g: 4, d: 6, t: ["naskh", "examples"], src: "al-Tirmidhī, Jāmiʿ, Kitāb al-Tafsīr (on Sūrat al-Mujādila); al-Ṭabarī, Jāmiʿ al-Bayān; al-Suyūṭī, al-Itqān", v: "58:12", w: 11,
    en: ["The verse shown asks believers who speak privately with the Messenger to give something first. What happened to this rule?", ["It was lifted by the next verse; a report says that ʿAlī was the only one who acted on it before it was abrogated", "It was made obligatory for ever", "It was moved to the verse on the Hajj", "It was never revealed in Madīna"], "The following verse relieves the believers of the duty to give charity before speaking with the Prophet, after they hesitated for fear of poverty. A report from ʿAlī in al-Tirmidhī says that he alone acted on the verse. It is a standard example of the abrogation of a ruling with a short life, and of the combination of a command with its relief."],
    de: ["Der gezeigte Vers fordert Gläubige, die unter vier Augen mit dem Gesandten sprechen, zuerst etwas zu geben. Was geschah mit dieser Regel?", ["Sie wurde durch den nächsten Vers aufgehoben; ein Bericht besagt, dass ʿAlī der Einzige war, der danach handelte, bevor sie aufgehoben wurde", "Sie wurde für immer verpflichtend gemacht", "Sie wurde in den Vers über den Ḥaǧǧ verlegt", "Sie wurde nie in Medina offenbart"], "Der folgende Vers nimmt den Gläubigen die Pflicht ab, vor dem Gespräch mit dem Propheten Almosen zu geben, nachdem sie aus Angst vor Armut zögerten. Ein Bericht von ʿAlī bei at-Tirmiḏī sagt, dass er allein nach dem Vers handelte. Es ist ein Standardbeispiel für die Aufhebung einer kurzlebigen Vorschrift und für die Verbindung eines Befehls mit seiner Erleichterung."],
    ar: ["الآية المعروضة تطلب ممن يناجي الرسول أن يقدم شيئًا أولًا. ما الذي حدث لهذا الحكم؟", ["رُفع بالآية التالية، وتروي رواية أن عليًّا وحده عمل به قبل نسخه", "صار واجبًا إلى الأبد", "نُقل إلى آية الحج", "لم ينزل في المدينة أصلًا"], "رفعت الآية التالية عن المؤمنين تقديم الصدقة قبل مناجاة النبي بعد أن أحجموا خوف الفقر، وفي رواية للترمذي عن علي أنه وحده عمل بالآية. وهي مثال معروف لنسخ حكم قصير الأمد ولاقتران الأمر بتخفيفه."] },

  { id: "xul-006", s: "ulum", g: 4, d: 6, t: ["naskh", "stoning-verse"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ḥudūd (ʿUmar’s sermon); Mālik, al-Muwaṭṭaʾ, Kitāb al-Ḥudūd; al-Suyūṭī, al-Itqān",
    en: ["What is the classical example of naskh al-tilāwa dūn al-ḥukm (abrogation of the wording with the ruling remaining)?", ["The ‘verse of stoning’, mentioned in ʿUmar’s address, whose wording is not in the muṣḥaf but whose ruling the Prophet carried out", "The verse on the year’s waiting for widows", "The change of the qibla", "The reduction of the ratio of fighters"], "In his address in Madīna, ʿUmar warned that people might say they did not find stoning in the Book, and affirmed that the Prophet and his successors stoned adulterers and that the verse had been recited. Scholars therefore cite it as an example of a wording lifted while the ruling stays. Some scholars, among them some Muʿtazilīs and Khawārij, reject the idea."],
    de: ["Was ist das klassische Beispiel für naskh at-tilāwa dūn al-ḥukm (Aufhebung des Wortlauts bei bleibendem Urteil)?", ["Der ‚Steinigungsvers‘, der in ʿUmars Ansprache erwähnt wird, dessen Wortlaut nicht im Muṣḥaf steht, dessen Urteil der Prophet aber vollzog", "Der Vers über die einjährige Wartezeit der Witwen", "Die Änderung der Qibla", "Die Herabsetzung des Verhältnisses der Kämpfer"], "In seiner Ansprache in Medina warnte ʿUmar, die Leute könnten sagen, sie fänden die Steinigung nicht im Buch, und bekräftigte, der Prophet und seine Nachfolger hätten Ehebrecher gesteinigt und der Vers sei rezitiert worden. Die Gelehrten führen ihn deshalb als Beispiel für einen aufgehobenen Wortlaut bei bleibendem Urteil an. Einige, darunter manche Muʿtaziliten und Ḫawāriǧ, lehnen den Gedanken ab."],
    ar: ["ما المثال الكلاسيكي لنسخ التلاوة دون الحكم؟", ["«آية الرجم» التي ذكرها عمر في خطبته وليست في المصحف وقد عمل النبي ﷺ بحكمها", "آية العدة سنة للأرملة", "تحويل القبلة", "تخفيف نسبة المقاتلين"], "حذّر عمر في خطبته بالمدينة من أن يقول الناس لا نجد الرجم في الكتاب، وأكد أن النبي ﷺ وخلفاءه رجموا الزناة وأن الآية قُرئت، فيُستشهد بها لما رُفعت تلاوته وبقي حكمه، وأنكر هذا القسم بعض المعتزلة والخوارج."] },

  { id: "xul-007", s: "ulum", g: 4, d: 7, t: ["naskh", "disagreement"], tr: ["comparative"], src: "al-Suyūṭī, al-Itqān, naw‘ 47; Shāh Walī Allāh al-Dihlawī, al-Fawz al-Kabīr fī Uṣūl al-Tafsīr; Ibn al-Jawzī, Nawāsikh al-Qurʾān",
    en: ["How did scholars differ over the number of abrogated verses in the Quran?", ["Earlier writers listed many, sometimes over a hundred verses; al-Suyūṭī accepted about twenty; Shāh Walī Allāh reduced them to about five", "All scholars agree there are exactly twenty-one", "All scholars agree there are none", "All agree on exactly five"], "Early authors, using a broad sense of naskh that included restriction, specification and alleviation, counted a large number. Al-Suyūṭī, in al-Itqān, kept only about twenty. Shāh Walī Allāh al-Dihlawī, treating many cases as takhṣīṣ or tafsīr, reduced the list to five. The variation shows that the dispute is about the definition of naskh more than about the verses."],
    de: ["Wie unterschieden sich die Gelehrten in der Zahl der aufgehobenen Verse im Koran?", ["Frühere Autoren listeten viele auf, manchmal über hundert Verse; as-Suyūṭī erkannte etwa zwanzig an; Šāh Walī Allāh reduzierte sie auf etwa fünf", "Alle Gelehrten sind sich einig, dass es genau einundzwanzig sind", "Alle Gelehrten sind sich einig, dass es keine gibt", "Alle sind sich über genau fünf einig"], "Frühe Autoren zählten mit einem weiten Begriff des Naskh, der Einschränkung, Spezifizierung und Erleichterung einschloss, eine große Zahl. As-Suyūṭī behielt in al-Itqān nur etwa zwanzig. Šāh Walī Allāh ad-Dihlawī, der viele Fälle als Taḫṣīṣ oder Tafsīr behandelte, reduzierte die Liste auf fünf. Die Abweichung zeigt, dass der Streit mehr die Definition des Naskh als die Verse betrifft."],
    ar: ["كيف اختلف العلماء في عدد الآيات المنسوخة في القرآن؟", ["عدّ المتقدمون عددًا كبيرًا قد يزيد على مئة آية، وقبل السيوطي نحو عشرين، وخفضها شاه ولي الله الدهلوي إلى نحو خمس", "اتفق العلماء على أنها إحدى وعشرون بالضبط", "اتفق العلماء على أنه لا منسوخ في القرآن", "اتفق الجميع على خمس بالضبط"], "توسع المتقدمون في معنى النسخ فشمل التقييد والتخصيص والتخفيف فكثر العدد، واقتصر السيوطي في «الإتقان» على نحو عشرين، وعدّ شاه ولي الله كثيرًا من الحالات تخصيصًا أو تفسيرًا فاقتصر على خمس، فالنزاع في تعريف النسخ أكثر منه في الآيات."] },

  { id: "xul-008", s: "ulum", g: 4, d: 7, t: ["naskh", "disagreement"], tr: ["comparative"], src: "Fakhr al-Dīn al-Rāzī, al-Tafsīr al-Kabīr, on 2:106; al-Suyūṭī, al-Itqān, naw‘ 47",
    en: ["Which scholar of the 4th century AH is known for denying that abrogation occurs in the Quran, limiting what others call naskh to specification?", ["Abū Muslim al-Iṣfahānī", "al-Shāfiʿī", "Abū ʿUbayd al-Qāsim ibn Sallām", "Makkī ibn Abī Ṭālib"], "Abū Muslim al-Iṣfahānī (d. 322 AH), a commentator of Muʿtazilī leanings, argued that nothing in the Quran is abrogated, interpreting the supposed cases as specification (takhṣīṣ) or time-limited rulings. His view is reported and rebutted by al-Rāzī and others, and is a minority position. The other scholars in the options wrote in favour of naskh."],
    de: ["Welcher Gelehrte des 4. Jh. n. H. ist dafür bekannt, bestritten zu haben, dass im Koran Aufhebung vorkommt, und das, was andere Naskh nennen, auf Spezifizierung zu beschränken?", ["Abū Muslim al-Iṣfahānī", "Aš-Šāfiʿī", "Abū ʿUbaid al-Qāsim ibn Sallām", "Makkī ibn Abī Ṭālib"], "Abū Muslim al-Iṣfahānī (gest. 322 n. H.), ein Kommentator mit muʿtazilitischer Neigung, vertrat, nichts im Koran sei aufgehoben, und deutete die angeblichen Fälle als Spezifizierung (Taḫṣīṣ) oder zeitlich begrenzte Urteile. Seine Ansicht wird von ar-Rāzī und anderen berichtet und widerlegt und ist eine Minderheitsposition. Die anderen Gelehrten in den Optionen schrieben zugunsten des Naskh."],
    ar: ["أي عالم من القرن الرابع الهجري اشتهر بإنكار وقوع النسخ في القرآن وحصر ما يسميه غيره نسخًا في التخصيص؟", ["أبو مسلم الأصفهاني", "الشافعي", "أبو عبيد القاسم بن سلام", "مكي بن أبي طالب"], "ذهب أبو مسلم الأصفهاني (ت 322هـ) وهو مفسر ذو ميل اعتزالي إلى أنه لا نسخ في القرآن وحمل ما يُظن نسخًا على التخصيص أو الأحكام المؤقتة، وقد نقل الرازي وغيره قوله وردّوه وهو قول الأقلية، أما بقية العلماء في الخيارات فكتبوا في إثبات النسخ."] },

  { id: "xul-009", s: "ulum", g: 4, d: 7, t: ["naskh", "usul-link"], tr: ["shafii", "hanafi", "comparative"], src: "al-Shāfiʿī, al-Risāla, bāb al-nāsikh wa-l-mansūkh; al-Sarakhsī, Uṣūl al-Sarakhsī; al-Ghazālī, al-Mustaṣfā",
    en: ["Which statement correctly gives the position of al-Shāfiʿī, as contrasted with that of the Ḥanafī school, on abrogation between the Quran and the Sunna?", ["Al-Shāfiʿī held that the Quran is not abrogated by the Sunna, only by the Quran, while the Ḥanafīs allowed an established (mutawātir or mashhūr) Sunna to abrogate the Quran", "Al-Shāfiʿī held that the Sunna abrogates the Quran and the Ḥanafīs denied it", "Both denied any abrogation across the two sources", "Both allowed any single report to abrogate the Quran"], "In al-Risāla, al-Shāfiʿī argued that God abrogates His Book only by His Book, and that the Sunna cannot cancel the Quran, since it merely explains it. The Ḥanafīs, who classify the mashhūr Sunna as a strong proof, permitted its abrogating a general Quranic ruling, as an example of the relation of takhṣīṣ. Both agree that a single report (khabar al-wāḥid) does not abrogate the Quran."],
    de: ["Welche Aussage gibt die Position aš-Šāfiʿīs im Gegensatz zu der der hanafitischen Schule zur Aufhebung zwischen Koran und Sunna richtig wieder?", ["Aš-Šāfiʿī meinte, der Koran werde nicht durch die Sunna aufgehoben, sondern nur durch den Koran, während die Hanafiten erlaubten, dass eine gesicherte (mutawātir oder mašhūr) Sunna den Koran aufhebt", "Aš-Šāfiʿī meinte, die Sunna hebe den Koran auf, und die Hanafiten bestritten es", "Beide bestritten jede Aufhebung zwischen den beiden Quellen", "Beide erlaubten, dass jeder Einzelbericht den Koran aufhebt"], "In ar-Risāla legte aš-Šāfiʿī dar, Gott hebe sein Buch nur durch sein Buch auf, und die Sunna könne den Koran nicht aufheben, da sie ihn nur erkläre. Die Hanafiten, die die mašhūr-Sunna als starken Beweis einstufen, erlaubten ihr, ein allgemeines koranisches Urteil aufzuheben, als Beispiel für das Verhältnis des Taḫṣīṣ. Beide sind sich einig, dass ein Einzelbericht (ḫabar al-wāḥid) den Koran nicht aufhebt."],
    ar: ["أي عبارة تبيّن على الوجه الصحيح موقف الشافعي في مقابل موقف الحنفية من النسخ بين القرآن والسنة؟", ["قال الشافعي إن القرآن لا تنسخه السنة وإنما ينسخه القرآن، وأجاز الحنفية أن تنسخ السنة الثابتة (المتواترة أو المشهورة) القرآن", "قال الشافعي إن السنة تنسخ القرآن وأنكر الحنفية ذلك", "أنكر الاثنان كل نسخ بين المصدرين", "أجاز الاثنان أن ينسخ أي خبر واحد القرآن"], "قرر الشافعي في «الرسالة» أن الله لا ينسخ كتابه إلا بكتابه وأن السنة لا تلغي القرآن لأنها بيان له، وأجاز الحنفية وهم يرون السنة المشهورة حجة قوية أن تنسخ حكمًا عامًّا في القرآن على نحو من التخصيص. ويتفق الفريقان على أن خبر الواحد لا ينسخ القرآن."] },

  { id: "xul-010", s: "ulum", g: 4, d: 6, t: ["naskh", "takhsis"], src: "al-Zarkashī, al-Burhān, naw‘ 31 (al-nāsikh wa-l-mansūkh); al-Ghazālī, al-Mustaṣfā; al-Suyūṭī, al-Itqān",
    en: ["What distinguishes naskh from takhṣīṣ (specification) in the classical works?", ["Naskh removes a ruling for the future after it had been in force for everything it covered; takhṣīṣ shows that part of the general wording was never meant", "They are exactly the same", "Naskh applies to reports, takhṣīṣ to commands only", "Naskh needs a later date, takhṣīṣ needs a Companion’s statement"], "Takhṣīṣ clarifies that a general text never included part of what it seems to cover, and can be done by a text that comes earlier, together with or later than it. Naskh lifts a ruling that applied from a given point and needs a later abrogating text. Naskh is confined to commands and prohibitions, not to reports of facts."],
    de: ["Was unterscheidet in den klassischen Werken Naskh von Taḫṣīṣ (Spezifizierung)?", ["Naskh hebt ein Urteil für die Zukunft auf, nachdem es für alles Erfasste in Kraft war; Taḫṣīṣ zeigt, dass ein Teil des allgemeinen Wortlauts nie gemeint war", "Sie sind genau dasselbe", "Naskh gilt für Berichte, Taḫṣīṣ nur für Befehle", "Naskh braucht ein späteres Datum, Taḫṣīṣ die Aussage eines Gefährten"], "Taḫṣīṣ stellt klar, dass ein allgemeiner Text einen Teil dessen, was er zu erfassen scheint, nie einschloss, und kann durch einen früheren, gleichzeitigen oder späteren Text geschehen. Naskh hebt ein Urteil auf, das ab einem bestimmten Zeitpunkt galt, und braucht einen späteren aufhebenden Text. Naskh ist auf Befehle und Verbote beschränkt, nicht auf Tatsachenberichte."],
    ar: ["ما الذي يميز النسخ عن التخصيص في كتب العلماء؟", ["النسخ رفع حكم للمستقبل بعد أن كان ثابتًا في كل ما يتناوله، والتخصيص بيان أن بعض اللفظ العام لم يكن مرادًا أصلًا", "هما شيء واحد تمامًا", "النسخ في الأخبار والتخصيص في الأوامر فقط", "النسخ يحتاج إلى تاريخ متأخر والتخصيص إلى قول صحابي"], "التخصيص بيان أن النص العام لم يتناول بعض ما يبدو أنه يشمله، ويجوز بنص متقدم أو مقارن أو متأخر، أما النسخ فرفع حكم كان ثابتًا من وقت معين ويحتاج إلى نص ناسخ متأخر، ويختص بالأوامر والنواهي لا بالأخبار."] },

  { id: "xul-011", s: "ulum", g: 4, d: 7, t: ["naskh", "knowing-naskh"], src: "al-Suyūṭī, al-Itqān, naw‘ 47; Makkī ibn Abī Ṭālib, al-Īḍāḥ li-Nāsikh al-Qurʾān wa-Mansūkhih; Ibn Ḥazm, al-Nāsikh wa-l-Mansūkh",
    en: ["By which means do the scholars say that abrogation may be established?", ["By a clear statement of the Prophet or of a Companion, by knowing which text came later, or by consensus; not by the opinion of a commentator alone", "By the preference of the commentator", "By the number of verses in a sūra", "By the order of the sūras in the muṣḥaf"], "Al-Suyūṭī and others say that abrogation is known by report (from the Prophet or a Companion who states that a verse abrogated another), by knowing the chronology of revelation, or by the community’s agreement. It cannot be decided by ijtihād, or by the order of the verses in the muṣḥaf, since the order of the muṣḥaf is not the order of revelation."],
    de: ["Auf welchen Wegen sagen die Gelehrten, dass eine Aufhebung festgestellt werden kann?", ["Durch eine klare Aussage des Propheten oder eines Gefährten, durch die Kenntnis, welcher Text später kam, oder durch Konsens; nicht allein durch die Meinung eines Kommentators", "Durch die Vorliebe des Kommentators", "Durch die Zahl der Verse einer Sure", "Durch die Reihenfolge der Suren im Muṣḥaf"], "As-Suyūṭī und andere sagen, Aufhebung werde durch Bericht erkannt (vom Propheten oder einem Gefährten, der sagt, ein Vers habe einen anderen aufgehoben), durch Kenntnis der Chronologie der Offenbarung oder durch Übereinstimmung der Gemeinschaft. Sie kann nicht durch Iǧtihād entschieden werden, auch nicht durch die Reihenfolge der Verse im Muṣḥaf, da diese nicht die Offenbarungsreihenfolge ist."],
    ar: ["بأي وسيلة يقول العلماء إن النسخ يثبت؟", ["بنص صريح عن النبي ﷺ أو صحابي، أو بمعرفة المتأخر من النصين، أو بالإجماع، لا برأي المفسر وحده", "بتفضيل المفسر", "بعدد آيات السورة", "بترتيب السور في المصحف"], "قال السيوطي وغيره إن النسخ يُعرف بالنقل عن النبي ﷺ أو عن صحابي يصرح بأن آية نسخت أخرى، أو بمعرفة تاريخ النزول، أو بإجماع الأمة، ولا يصح بالاجتهاد ولا بترتيب الآيات في المصحف لأن ترتيب المصحف ليس ترتيب النزول."] },

  { id: "xul-012", s: "ulum", g: 4, d: 6, t: ["naskh", "classical-works"], src: "Makkī ibn Abī Ṭālib, al-Īḍāḥ li-Nāsikh al-Qurʾān wa-Mansūkhih; Abū ʿUbayd, al-Nāsikh wa-l-Mansūkh; Ibn al-Jawzī, Nawāsikh al-Qurʾān",
    en: ["Which work on abrogation by Makkī ibn Abī Ṭālib is a standard classical source, alongside the works of Abū ʿUbayd and Ibn al-Jawzī?", ["al-Īḍāḥ li-Nāsikh al-Qurʾān wa-Mansūkhih", "al-Kashf ʿan Wujūh al-Qirāʾāt", "al-Hidāya ilā Bulūgh al-Nihāya", "al-Ri'āya li-Tajwīd al-Qirāʾa"], "Makkī (d. 437 AH) of Qayrawān and Córdoba wrote al-Īḍāḥ li-Nāsikh al-Qurʾān wa-Mansūkhih. Several of his other works are on qirāʾāt and tajwīd (al-Kashf, al-Riʿāya) and on tafsīr (al-Hidāya). Abū ʿUbayd and Ibn al-Jawzī (Nawāsikh al-Qurʾān) wrote earlier and later works on the same topic."],
    de: ["Welches Werk Makkī ibn Abī Ṭālibs über die Aufhebung ist eine klassische Standardquelle, neben den Werken von Abū ʿUbaid und Ibn al-Ǧauzī?", ["Al-Īḍāḥ li-Nāsiḫ al-Qurʾān wa-Mansūḫihi", "Al-Kašf ʿan Wuǧūh al-Qirāʾāt", "Al-Hidāya ilā Bulūġ an-Nihāya", "Ar-Riʿāya li-Taǧwīd al-Qirāʾa"], "Makkī (gest. 437 n. H.) von Qairawān und Córdoba schrieb al-Īḍāḥ li-Nāsiḫ al-Qurʾān wa-Mansūḫihi. Mehrere seiner anderen Werke gelten den Qirāʾāt und dem Tağwīd (al-Kašf, ar-Riʿāya) und dem Tafsīr (al-Hidāya). Abū ʿUbaid und Ibn al-Ǧauzī (Nawāsiḫ al-Qurʾān) schrieben frühere und spätere Werke zum selben Thema."],
    ar: ["أي كتاب لمكي بن أبي طالب في النسخ مصدر كلاسيكي معياري إلى جانب كتابي أبي عبيد وابن الجوزي؟", ["الإيضاح لناسخ القرآن ومنسوخه", "الكشف عن وجوه القراءات", "الهداية إلى بلوغ النهاية", "الرعاية لتجويد القراءة"], "ألّف مكي (ت 437هـ) القيرواني ثم القرطبي «الإيضاح لناسخ القرآن ومنسوخه»، وله كتب أخرى في القراءات والتجويد (الكشف والرعاية) وفي التفسير (الهداية)، وكتب أبو عبيد وابن الجوزي (نواسخ القرآن) قبله وبعده في الموضوع نفسه."] },

  { id: "xul-013", s: "ulum", g: 4, d: 6, t: ["ijaz", "challenge-verses"], src: "al-Bāqillānī, Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān, naw‘ 64 (iʿjāz al-Qurʾān)", v: "11:13", w: 6,
    en: ["The verse shown challenges the unbelievers to produce ten sūras. What is the usual order of the challenges in the Quran, according to the scholars?", ["The whole Quran (17:88), then ten sūras (11:13), then one sūra (10:38), then one sūra again in Madīna (2:23)", "One sūra first, then ten sūras, then the whole Quran", "Ten sūras first, then the whole Quran, then one sūra", "Only the whole Quran was ever required"], "Commentators note a descent in the challenge: first to the whole Quran, with men and jinn together; then ten sūras; then a single sūra in the Meccan period and again in the Madinan period. The sequence is used to argue that the challenge applied to even the smallest portion, a sūra."],
    de: ["Der gezeigte Vers fordert die Ungläubigen heraus, zehn Suren hervorzubringen. Wie ist nach den Gelehrten die übliche Reihenfolge der Herausforderungen im Koran?", ["Der ganze Koran (17:88), dann zehn Suren (11:13), dann eine Sure (10:38), dann wieder eine Sure in Medina (2:23)", "Zuerst eine Sure, dann zehn Suren, dann der ganze Koran", "Zuerst zehn Suren, dann der ganze Koran, dann eine Sure", "Verlangt wurde stets nur der ganze Koran"], "Die Kommentatoren halten eine Abstufung der Herausforderung fest: zuerst der ganze Koran, mit Menschen und Ǧinn zusammen; dann zehn Suren; dann eine einzelne Sure in der mekkanischen Zeit und erneut in der medinensischen Zeit. Die Reihenfolge wird genutzt, um zu zeigen, dass die Herausforderung auch für den kleinsten Teil, eine Sure, galt."],
    ar: ["تتحدى الآية المعروضة الكفار بأن يأتوا بعشر سور. ما الترتيب المشهور للتحديات في القرآن عند العلماء؟", ["بالقرآن كله (الإسراء 88) ثم عشر سور (هود 13) ثم سورة (يونس 38) ثم سورة في المدينة (البقرة 23)", "بسورة أولًا ثم عشر سور ثم القرآن كله", "بعشر سور أولًا ثم القرآن كله ثم سورة", "لم يُطلب إلا القرآن كله"], "يلاحظ المفسرون تدرّجًا في التحدي من القرآن كله بالإنس والجن معًا، إلى عشر سور، ثم إلى سورة واحدة في العهد المكي وتكرر في العهد المدني، ويُستدل بالتدرج على أن التحدي شمل أصغر وحدة وهي السورة."] },

  { id: "xul-014", s: "ulum", g: 4, d: 7, t: ["ijaz", "sarfa"], tr: ["comparative"], src: "al-Bāqillānī, Iʿjāz al-Qurʾān, refutation of the ṣarfa; al-Khaṭṭābī, Bayān Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān",
    en: ["What is the view called ṣarfa on the inimitability of the Quran, and who held it?", ["That God turned people away from imitating the Quran though they would otherwise have been able; held by al-Naẓẓām and some Muʿtazilīs and rejected by most scholars", "That the Quran is inimitable only for its rhyme; held by al-Bāqillānī", "That the Quran can be imitated but no one tried; held by al-Jurjānī", "That the Quran is inimitable only for its prophecies; held by al-Khaṭṭābī"], "The ṣarfa theory, attributed to Ibrāhīm al-Naẓẓām and later to others, held that the Arabs were able to produce a text like it but God took away their ability. Most scholars, including al-Bāqillānī, al-Khaṭṭābī and al-Jurjānī, rejected it, saying the inimitability is in the Quran itself, in its composition and meanings. They noted that if the Arabs had been merely prevented, the Quran would not have been a miracle in itself."],
    de: ["Was ist die Ṣarfa genannte Ansicht zur Unnachahmlichkeit des Korans, und wer vertrat sie?", ["Dass Gott die Menschen davon abwandte, den Koran nachzuahmen, obwohl sie sonst dazu fähig gewesen wären; vertreten von an-Naẓẓām und einigen Muʿtaziliten, von den meisten Gelehrten abgelehnt", "Dass der Koran nur wegen seines Reims unnachahmlich ist; vertreten von al-Bāqillānī", "Dass der Koran nachahmbar ist, aber niemand es versuchte; vertreten von al-Ǧurǧānī", "Dass der Koran nur wegen seiner Voraussagen unnachahmlich ist; vertreten von al-Ḫaṭṭābī"], "Die Ṣarfa-Theorie, Ibrāhīm an-Naẓẓām und später anderen zugeschrieben, besagte, die Araber hätten einen ähnlichen Text hervorbringen können, doch Gott habe ihnen die Fähigkeit genommen. Die meisten Gelehrten, darunter al-Bāqillānī, al-Ḫaṭṭābī und al-Ǧurǧānī, lehnten sie ab, da die Unnachahmlichkeit im Koran selbst liege, in seiner Komposition und seinen Bedeutungen. Sie wandten ein, dass der Koran, wären die Araber nur gehindert worden, nicht an sich ein Wunder wäre."],
    ar: ["ما القول المسمى بالصرفة في إعجاز القرآن ومن قال به؟", ["أن الله صرف الناس عن معارضته مع قدرتهم عليها، وقال به النظّام وبعض المعتزلة وردّه أكثر العلماء", "أن الإعجاز في الفواصل وحدها، وقال به الباقلاني", "أن القرآن يمكن معارضته ولكن لم يحاول أحد، وقال به الجرجاني", "أن الإعجاز في الإخبار بالغيب وحده، وقال به الخطابي"], "نُسبت الصرفة إلى إبراهيم النظّام ثم غيره، ومؤداها أن العرب كانوا قادرين على الإتيان بمثله لكن الله سلبهم القدرة. وردّها أكثر العلماء كالباقلاني والخطابي والجرجاني وقالوا إن الإعجاز في القرآن نفسه نظمًا ومعنى، ولو كان مجرد منع لما كان القرآن معجزة في ذاته."] },

  { id: "xul-015", s: "ulum", g: 4, d: 7, t: ["ijaz", "rummani"], src: "al-Rummānī, al-Nukat fī Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān, naw‘ 64",
    en: ["In his al-Nukat fī Iʿjāz al-Qurʾān, how does al-Rummānī describe the aspects of inimitability?", ["He lists seven, including leaving the challenge unanswered, the challenge to all, the ṣarfa, eloquence, true reports of the future, the breaking of the norm, and comparison with other miracles", "He lists only eloquence", "He lists only the prophecies", "He lists only the ṣarfa"], "Al-Rummānī (d. 384 AH) said that inimitability appears in seven aspects: abandonment of the challenge despite strong motives, the challenge to all people, ṣarfa, balāgha, true reports about the future, breaking of the norm, and comparison with other signs. That he includes the ṣarfa among the aspects, alongside eloquence, was criticised by later scholars who insisted on the Quran’s intrinsic quality."],
    de: ["Wie beschreibt ar-Rummānī in seinem al-Nukat fī Iʿǧāz al-Qurʾān die Aspekte der Unnachahmlichkeit?", ["Er nennt sieben, darunter das Ausbleiben einer Antwort auf die Herausforderung, die Herausforderung an alle, die Ṣarfa, die Beredsamkeit, wahre Berichte über die Zukunft, den Bruch der Gewohnheit und den Vergleich mit anderen Wundern", "Er nennt nur die Beredsamkeit", "Er nennt nur die Voraussagen", "Er nennt nur die Ṣarfa"], "Ar-Rummānī (gest. 384 n. H.) sagte, die Unnachahmlichkeit zeige sich in sieben Aspekten: Verzicht auf die Antwort trotz starker Beweggründe, Herausforderung an alle Menschen, Ṣarfa, Balāġa, wahre Berichte über die Zukunft, Bruch der Gewohnheit und Vergleich mit anderen Zeichen. Dass er die Ṣarfa neben der Beredsamkeit aufführt, wurde von späteren Gelehrten kritisiert, die auf der inneren Qualität des Korans bestanden."],
    ar: ["كيف يعرض الرماني وجوه الإعجاز في «النكت في إعجاز القرآن»؟", ["يذكر سبعة منها ترك المعارضة والتحدي للكافة والصرفة والبلاغة والأخبار الصادقة عن المستقبل ونقض العادة والقياس بكل معجزة", "يذكر البلاغة وحدها", "يذكر الأخبار بالغيب وحدها", "يذكر الصرفة وحدها"], "قال الرماني (ت 384هـ) إن الإعجاز يظهر في سبعة وجوه: ترك المعارضة مع توافر الدواعي، والتحدي للكافة، والصرفة، والبلاغة، والأخبار الصادقة عن الأمور المستقبلة، ونقض العادة، وقياسه بكل معجزة. وانتقد المتأخرون ذكره الصرفة بجانب البلاغة لأنهم أصروا على أن الإعجاز في ذات القرآن."] },

  { id: "xul-016", s: "ulum", g: 4, d: 6, t: ["ijaz", "classical-works"], src: "al-Suyūṭī, Muʿtarak al-Aqrān fī Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān",
    en: ["Who wrote Muʿtarak al-Aqrān fī Iʿjāz al-Qurʾān, a large study of the inimitability of the Quran?", ["Jalāl al-Dīn al-Suyūṭī", "Badr al-Dīn al-Zarkashī", "Ibn Qutayba", "al-Rāghib al-Iṣfahānī"], "Al-Suyūṭī (d. 911 AH) wrote Muʿtarak al-Aqrān, a work on the inimitability of the Quran, in addition to the encyclopaedic al-Itqān. Al-Zarkashī is the author of al-Burhān, a main source of al-Itqān; Ibn Qutayba wrote Taʾwīl Mushkil al-Qurʾān; and al-Rāghib is the author of al-Mufradāt."],
    de: ["Wer schrieb Muʿtarak al-Aqrān fī Iʿǧāz al-Qurʾān, eine große Studie über die Unnachahmlichkeit des Korans?", ["Ǧalāl ad-Dīn as-Suyūṭī", "Badr ad-Dīn az-Zarkašī", "Ibn Qutaiba", "Ar-Rāġib al-Iṣfahānī"], "As-Suyūṭī (gest. 911 n. H.) schrieb Muʿtarak al-Aqrān, ein Werk über die Unnachahmlichkeit des Korans, zusätzlich zum enzyklopädischen al-Itqān. Az-Zarkašī ist der Autor von al-Burhān, einer Hauptquelle von al-Itqān; Ibn Qutaiba schrieb Taʾwīl Muškil al-Qurʾān, und ar-Rāġib ist Autor von al-Mufradāt."],
    ar: ["من الذي ألّف «معترك الأقران في إعجاز القرآن» وهو دراسة كبيرة في إعجاز القرآن؟", ["جلال الدين السيوطي", "بدر الدين الزركشي", "ابن قتيبة", "الراغب الأصفهاني"], "ألّف السيوطي (ت 911هـ) «معترك الأقران» في إعجاز القرآن إضافة إلى الموسوعة «الإتقان»، أما الزركشي فصاحب «البرهان» وهو مصدر أساسي للإتقان، وابن قتيبة صاحب «تأويل مشكل القرآن»، والراغب صاحب «المفردات»."] },

  { id: "xul-017", s: "ulum", g: 4, d: 6, t: ["classical-works", "encyclopaedias"], src: "al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān; al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān",
    en: ["How many branches (anwāʿ) does al-Suyūṭī’s al-Itqān discuss, and how many does al-Zarkashī’s al-Burhān?", ["Eighty in al-Itqān and forty-seven in al-Burhān", "Forty-seven in al-Itqān and eighty in al-Burhān", "Seventy in both", "Twelve in both"], "Al-Zarkashī (d. 794 AH) divided al-Burhān fī ʿUlūm al-Qurʾān into forty-seven types, and al-Suyūṭī (d. 911 AH), building on it and on al-Balqīnī’s work, arranged al-Itqān in eighty types. The latter is the standard textbook in the Quranic sciences."],
    de: ["Wie viele Zweige (anwāʿ) behandelt as-Suyūṭīs al-Itqān und wie viele az-Zarkašīs al-Burhān?", ["Achtzig in al-Itqān und siebenundvierzig in al-Burhān", "Siebenundvierzig in al-Itqān und achtzig in al-Burhān", "Siebzig in beiden", "Zwölf in beiden"], "Az-Zarkašī (gest. 794 n. H.) gliederte al-Burhān fī ʿUlūm al-Qurʾān in siebenundvierzig Arten, und as-Suyūṭī (gest. 911 n. H.) ordnete, darauf und auf dem Werk al-Balqīnīs aufbauend, al-Itqān in achtzig Arten. Letzteres ist das Standardlehrbuch der Koranwissenschaften."],
    ar: ["كم نوعًا يبحث «الإتقان» للسيوطي وكم نوعًا يبحث «البرهان» للزركشي؟", ["ثمانين في الإتقان وسبعة وأربعين في البرهان", "سبعة وأربعين في الإتقان وثمانين في البرهان", "سبعين في كليهما", "اثني عشر في كليهما"], "قسّم الزركشي (ت 794هـ) «البرهان في علوم القرآن» إلى سبعة وأربعين نوعًا، وبنى السيوطي (ت 911هـ) على عمله وعمل البلقيني «الإتقان» في ثمانين نوعًا، وهو الكتاب المدرسي المعتمد في علوم القرآن."] },

  { id: "xul-018", s: "ulum", g: 4, d: 6, t: ["asbab-al-nuzul", "usul"], tr: ["jumhur"], src: "al-Suyūṭī, al-Itqān, naw‘ 9 (asbāb al-nuzūl); al-Zarkashī, al-Burhān; al-Shāṭibī, al-Muwāfaqāt",
    en: ["Which principle do most scholars follow when a verse was revealed for a specific occasion but is worded generally?", ["The consideration is with the generality of the wording, not the specificity of the occasion", "The consideration is with the specificity of the occasion alone", "The verse applies only to the persons of the occasion", "The verse is abrogated after the occasion"], "The majority of uṣūlīs and commentators say that the ruling of a general text applies to all cases it covers, and the cause serves to explain and to show that this case is definitely included. Some scholars, a small group, held that it is limited to the occasion. The principle is cited in the discussion of asbāb al-nuzūl in al-Itqān."],
    de: ["Welchem Grundsatz folgen die meisten Gelehrten, wenn ein Vers zu einem bestimmten Anlass offenbart wurde, aber allgemein formuliert ist?", ["Maßgeblich ist die Allgemeinheit des Wortlauts, nicht die Besonderheit des Anlasses", "Maßgeblich ist allein die Besonderheit des Anlasses", "Der Vers gilt nur für die Personen des Anlasses", "Der Vers ist nach dem Anlass aufgehoben"], "Die Mehrheit der Uṣūlīs und Kommentatoren sagt, das Urteil eines allgemeinen Textes gelte für alle Fälle, die er erfasst, und der Anlass diene der Erläuterung und dazu zu zeigen, dass dieser Fall sicher eingeschlossen ist. Einige, eine kleine Gruppe, meinten, es sei auf den Anlass beschränkt. Der Grundsatz wird in der Erörterung der Asbāb an-nuzūl in al-Itqān angeführt."],
    ar: ["أي قاعدة يتبعها أكثر العلماء حين تنزل آية لسبب خاص وصيغتها عامة؟", ["العبرة بعموم اللفظ لا بخصوص السبب", "العبرة بخصوص السبب وحده", "تنطبق الآية على أشخاص السبب فقط", "تُنسخ الآية بعد السبب"], "يقول جمهور الأصوليين والمفسرين إن حكم النص العام يشمل كل ما يتناوله، وإن السبب يفسّر ويبيّن أن صورته داخلة قطعًا، وذهب بعضهم قلة إلى الاقتصار على السبب، وتُذكر القاعدة في بحث أسباب النزول من الإتقان."] },

  { id: "xul-019", s: "ulum", g: 4, d: 7, t: ["asbab-al-nuzul", "methodology"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; al-Suyūṭī, al-Itqān, naw‘ 9; al-Zarkashī, al-Burhān",
    en: ["What caution does Ibn Taymiyya give about the wording ‘this verse was revealed concerning such-and-such’ in the reports of the Companions and Successors?", ["It may mean that the verse includes the case, as an explanation, not necessarily that this was the actual cause that led to its revelation", "It always means a precise chronological cause", "It always means the verse is abrogated", "It always indicates a late addition to the text"], "In the Muqaddima fī Uṣūl al-Tafsīr, Ibn Taymiyya says that the Companions and Successors often said ‘this verse was revealed about so-and-so’ meaning that the verse covers it, like a tafsīr. A report is therefore treated as a true cause only if it is stated that the event happened and the verse came in reply. This clarifies why some reports of asbāb contradict each other without contradiction."],
    de: ["Welche Vorsicht mahnt Ibn Taimiyya bei der Wendung ‚dieser Vers wurde über so und so offenbart‘ in den Berichten der Gefährten und Nachfolger an?", ["Sie kann bedeuten, dass der Vers den Fall einschließt, als Erläuterung, nicht unbedingt dass dies der tatsächliche Anlass der Offenbarung war", "Sie bedeutet immer einen genauen zeitlichen Anlass", "Sie bedeutet immer, dass der Vers aufgehoben ist", "Sie weist immer auf einen späten Zusatz zum Text hin"], "In der Muqaddima fī Uṣūl at-Tafsīr sagt Ibn Taimiyya, die Gefährten und Nachfolger hätten oft gesagt ‚dieser Vers wurde über den und den offenbart‘, womit gemeint sei, dass der Vers ihn einschließt, wie ein Tafsīr. Ein Bericht gilt daher nur dann als echter Anlass, wenn gesagt wird, dass sich das Ereignis ereignete und der Vers als Antwort kam. Das erklärt, warum manche Berichte über Asbāb einander ohne Widerspruch zu widersprechen scheinen."],
    ar: ["ما التنبيه الذي يذكره ابن تيمية في قول الصحابة والتابعين «نزلت هذه الآية في كذا»؟", ["قد يراد به أن الآية تتناول هذه الصورة على جهة التفسير لا أنه السبب الفعلي لنزولها", "يراد به دائمًا سبب تاريخي دقيق", "يراد به دائمًا أن الآية منسوخة", "يدل دائمًا على إضافة متأخرة للنص"], "يبين ابن تيمية في «مقدمة في أصول التفسير» أن الصحابة والتابعين كثيرًا ما يقولون نزلت هذه الآية في كذا ويقصدون أنها تتناوله كالتفسير، فلا تُعدّ الرواية سببًا حقيقيًّا إلا إذا صرّحت بوقوع الحادثة ونزول الآية جوابًا لها. وهذا يفسر وجود روايات في أسباب النزول تبدو متعارضة ولا تتناقض."] },

  { id: "xul-020", s: "ulum", g: 4, d: 6, t: ["asbab-al-nuzul", "classical-works"], src: "al-Wāḥidī, Asbāb al-Nuzūl; al-Suyūṭī, Lubāb al-Nuqūl fī Asbāb al-Nuzūl",
    en: ["Which pair of authors and works on asbāb al-nuzūl is correct?", ["al-Wāḥidī: Asbāb al-Nuzūl; al-Suyūṭī: Lubāb al-Nuqūl fī Asbāb al-Nuzūl", "al-Wāḥidī: Lubāb al-Nuqūl; al-Suyūṭī: Asbāb al-Nuzūl", "al-Zarkashī: Asbāb al-Nuzūl; al-Suyūṭī: al-Burhān", "Ibn Ḥajar: Asbāb al-Nuzūl; al-Wāḥidī: al-Itqān"], "Al-Wāḥidī al-Nīsābūrī (d. 468 AH) wrote the best-known classical collection of reports about the occasions of revelation, often criticised for including weak reports; al-Suyūṭī (d. 911 AH) wrote Lubāb al-Nuqūl, a book of sounder reports in an abridged form. Ibn Ḥajar also wrote on the topic in other works."],
    de: ["Welches Paar von Autoren und Werken über Asbāb an-nuzūl ist richtig?", ["Al-Wāḥidī: Asbāb an-Nuzūl; as-Suyūṭī: Lubāb an-Nuqūl fī Asbāb an-Nuzūl", "Al-Wāḥidī: Lubāb an-Nuqūl; as-Suyūṭī: Asbāb an-Nuzūl", "Az-Zarkašī: Asbāb an-Nuzūl; as-Suyūṭī: al-Burhān", "Ibn Ḥaǧar: Asbāb an-Nuzūl; al-Wāḥidī: al-Itqān"], "Al-Wāḥidī an-Nīsābūrī (gest. 468 n. H.) schrieb die bekannteste klassische Sammlung von Berichten über die Offenbarungsanlässe, oft kritisiert, weil sie schwache Berichte enthält; as-Suyūṭī (gest. 911 n. H.) schrieb Lubāb an-Nuqūl, ein Buch mit gesünderen Berichten in verkürzter Form. Auch Ibn Ḥaǧar schrieb in anderen Werken zum Thema."],
    ar: ["أي اقتران بين المؤلفين وكتبهم في أسباب النزول صحيح؟", ["الواحدي: أسباب النزول؛ السيوطي: لباب النقول في أسباب النزول", "الواحدي: لباب النقول؛ السيوطي: أسباب النزول", "الزركشي: أسباب النزول؛ السيوطي: البرهان", "ابن حجر: أسباب النزول؛ الواحدي: الإتقان"], "ألّف الواحدي النيسابوري (ت 468هـ) أشهر مجموعة كلاسيكية في أسباب النزول وانتُقد لإيراده روايات ضعيفة، وألّف السيوطي (ت 911هـ) «لباب النقول» في روايات أصح مختصرة، وكتب ابن حجر في الموضوع في مصنفات أخرى."] },

  { id: "xul-021", s: "ulum", g: 4, d: 6, t: ["makki-madani", "criteria"], src: "al-Suyūṭī, al-Itqān, naw‘ 1 (al-makkī wa-l-madanī); al-Zarkashī, al-Burhān, naw‘ 3",
    en: ["By which three criteria do scholars distinguish Makkan from Madinan revelation, and which is most widely used?", ["By time (before or after the Hijra), by place, and by the addressee; the criterion of time is the most widely used", "By length, by rhyme and by theme; theme is most used", "By the Companion who reported it, by the reader and by the chain; the chain is most used", "By the first word, the last word and the middle word; the first word is most used"], "The three criteria are the time (Makkan is what was revealed before the Hijra, even if outside Makka), the place (what was revealed in Makka and surroundings) and the addressee (those addressed). The first is most widely accepted because it divides the entire Quran. On the time criterion, verses revealed during the journey of the Hijra or at Ḥudaybiya and the conquest are Madinan."],
    de: ["Nach welchen drei Kriterien unterscheiden Gelehrte mekkanische von medinensischer Offenbarung, und welches wird am häufigsten gebraucht?", ["Nach der Zeit (vor oder nach der Hidschra), nach dem Ort und nach dem Angesprochenen; das Zeitkriterium wird am häufigsten gebraucht", "Nach Länge, Reim und Thema; das Thema wird am häufigsten gebraucht", "Nach dem berichtenden Gefährten, dem Leser und der Kette; die Kette wird am häufigsten gebraucht", "Nach dem ersten, dem letzten und dem mittleren Wort; das erste Wort wird am häufigsten gebraucht"], "Die drei Kriterien sind die Zeit (mekkanisch ist, was vor der Hidschra offenbart wurde, auch außerhalb Mekkas), der Ort (was in Mekka und Umgebung offenbart wurde) und der Angesprochene (die Adressaten). Das erste ist am meisten anerkannt, weil es den ganzen Koran einteilt. Nach dem Zeitkriterium gelten Verse, die auf der Reise der Hidschra, bei Ḥudaibiya oder bei der Eroberung offenbart wurden, als medinensisch."],
    ar: ["بأي ثلاثة معايير يميز العلماء المكي من المدني، وأيها الأشهر؟", ["بالزمان (قبل الهجرة أو بعدها) وبالمكان وبالمخاطَب، وأشهرها معيار الزمان", "بالطول والفاصلة والموضوع، وأشهرها الموضوع", "بالصحابي الراوي والقارئ والسند، وأشهرها السند", "بالكلمة الأولى والأخيرة والوسطى، وأشهرها الكلمة الأولى"], "المعايير الثلاثة: الزمان (المكي ما نزل قبل الهجرة ولو خارج مكة)، والمكان (ما نزل بمكة وما حولها)، والمخاطَب (من وُجّه إليهم الخطاب)، والأول أشهرها لأنه يقسم القرآن كله، وعلى معيار الزمان تعدّ الآيات النازلة في طريق الهجرة وعام الحديبية والفتح مدنية."] },

  { id: "xul-022", s: "ulum", g: 4, d: 6, t: ["makki-madani", "features"], src: "al-Suyūṭī, al-Itqān, naw‘ 1; al-Zarkashī, al-Burhān",
    en: ["Which features do the classical works associate with Makkan sūras rather than Madinan ones, as general tendencies and not strict rules?", ["The call ‘O people’, the word kallā (nay), short verses with strong rhythm, and themes of tawḥīd, resurrection and stories of earlier prophets", "Long legal passages about inheritance, fasting and warfare", "The call ‘O you who believe’ throughout", "Rules on the Hajj and on treaties with the People of the Book"], "The scholars identify tendencies: Makkan sūras use ‘O people’ (and not ‘O you who believe’), kallā, oaths and short, rhythmic verses, and deal with belief, afterlife and earlier nations. Madinan sūras have longer verses, legal rulings (inheritance, fasting, jihad, hypocrites) and address the believers and the People of the Book. Exceptions exist, as with 22:77."],
    de: ["Welche Merkmale verbinden die klassischen Werke eher mit mekkanischen als mit medinensischen Suren, als allgemeine Tendenzen und nicht als strenge Regeln?", ["Die Anrede ‚O ihr Menschen‘, das Wort kallā (nein), kurze Verse mit starkem Rhythmus und die Themen Tawḥīd, Auferstehung und Geschichten früherer Propheten", "Lange Rechtspassagen über Erbe, Fasten und Kriegführung", "Die Anrede ‚O ihr, die ihr glaubt‘ durchgehend", "Regeln zum Ḥaǧǧ und zu Verträgen mit den Leuten des Buches"], "Die Gelehrten nennen Tendenzen: Mekkanische Suren gebrauchen ‚O ihr Menschen‘ (und nicht ‚O ihr, die ihr glaubt‘), kallā, Schwüre und kurze, rhythmische Verse und behandeln Glauben, Jenseits und frühere Völker. Medinensische Suren haben längere Verse, Rechtsurteile (Erbe, Fasten, Ǧihād, Heuchler) und wenden sich an die Gläubigen und die Leute des Buches. Ausnahmen gibt es, etwa bei 22:77."],
    ar: ["ما الخصائص التي تربطها الكتب القديمة بالسور المكية دون المدنية بوصفها ميولًا عامة لا قواعد صارمة؟", ["نداء الناس ولفظ «كلا» والآيات القصيرة ذات الإيقاع القوي وموضوعات التوحيد والبعث وقصص الأنبياء السابقين", "المقاطع الفقهية الطويلة في الميراث والصيام والقتال", "نداء الذين آمنوا في كل موضع", "أحكام الحج والمعاهدات مع أهل الكتاب"], "يحدد العلماء ميولًا: تكثر في المكي ندا الناس وكلا والقسم والآيات القصيرة الموقعة، وموضوعات العقيدة والآخرة والأمم السابقة، وفي المدني آيات أطول وأحكام تشريعية (ميراث وصيام وجهاد ومنافقون) وخطاب للمؤمنين ولأهل الكتاب، وفيهما استثناءات كالحج 77."] },

  { id: "xul-023", s: "ulum", g: 4, d: 7, t: ["makki-madani", "disputed-surahs"], tr: ["comparative"], src: "al-Suyūṭī, al-Itqān, naw‘ 1; Ibn Kathīr, Tafsīr, on Sūrat al-Fātiḥa",
    en: ["Which statement correctly describes the scholarly record on whether Sūrat al-Fātiḥa is Makkan or Madinan?", ["The majority hold it is Makkan; some reports (from Abū Hurayra and Mujāhid) say Madinan; and some say it was revealed twice", "All scholars agree it is Madinan", "All scholars agree it is Makkan", "No scholar has ever discussed it"], "Al-Suyūṭī records three views: Makkan (the majority, since prayer was already established with it in Makka), Madinan (a report attributed to Abū Hurayra and Mujāhid), and a view that it was revealed twice, once in each city. The first is preferred because the opening sūra is associated with the early period of prayer."],
    de: ["Welche Aussage beschreibt den Stand der Gelehrten zur Frage, ob Sure al-Fātiḥa mekkanisch oder medinensisch ist, richtig?", ["Die Mehrheit hält sie für mekkanisch; einige Berichte (von Abū Huraira und Muǧāhid) sagen medinensisch; und manche sagen, sie sei zweimal offenbart worden", "Alle Gelehrten sind sich einig, sie sei medinensisch", "Alle Gelehrten sind sich einig, sie sei mekkanisch", "Kein Gelehrter hat je darüber gesprochen"], "As-Suyūṭī verzeichnet drei Ansichten: mekkanisch (die Mehrheit, da das Gebet schon in Mekka mit ihr verrichtet wurde), medinensisch (ein Abū Huraira und Muǧāhid zugeschriebener Bericht) und die Ansicht, sie sei zweimal offenbart worden, einmal in jeder Stadt. Die erste wird bevorzugt, weil die Eröffnungssure mit der frühen Zeit des Gebets verbunden ist."],
    ar: ["أي عبارة تصف سجل العلماء على الوجه الصحيح في كون سورة الفاتحة مكية أو مدنية؟", ["الجمهور على أنها مكية، وروي عن أبي هريرة ومجاهد أنها مدنية، وقيل نزلت مرتين", "اتفق العلماء على أنها مدنية", "اتفق العلماء على أنها مكية", "لم يتكلم فيها أحد من العلماء"], "ذكر السيوطي ثلاثة أقوال: مكية وهو قول الجمهور لأن الصلاة كانت بها في مكة، ومدنية وهو رواية تُنسب إلى أبي هريرة ومجاهد، وأنها نزلت مرتين مرة في كل مدينة، ويُرجَّح الأول لارتباط السورة بأول عهد الصلاة."] },

  { id: "xul-024", s: "ulum", g: 4, d: 7, t: ["chronology", "last-revealed"], tr: ["comparative"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr (on 4:176 and Sūrat Barāʾa); al-Nasāʾī, Sunan; al-Suyūṭī, al-Itqān, naw‘ 3 (ākhir mā nazala)", v: "2:281", w: 1,
    en: ["Different reports name the last verse or sūra revealed. Which statement correctly pairs the reports with their narrators?", ["Ibn ʿAbbās is reported to have named the verse shown (about guarding against a Day of return to God); al-Barāʾ ibn ʿĀzib named the last verse of al-Nisāʾ and Barāʾa as the last complete sūra", "ʿUmar named Sūrat al-Fātiḥa and al-Barāʾ named al-Ikhlāṣ", "All Companions agreed on 2:281 alone", "All named Sūrat al-Naṣr as a verse"], "The sources preserve several statements. Ibn ʿAbbās is quoted for 2:281 (in one report, the last before the Prophet’s death, about nine nights before); al-Barāʾ for 4:176 as the last verse and Barāʾa as the last complete sūra (al-Bukhārī). Scholars reconcile these by taking each as ‘last’ in a particular subject or by the narrator’s knowledge."],
    de: ["Verschiedene Berichte nennen den letzten offenbarten Vers oder die letzte Sure. Welche Aussage ordnet die Berichte ihren Erzählern richtig zu?", ["Von Ibn ʿAbbās wird berichtet, er habe den gezeigten Vers (über die Wahrung vor einem Tag der Rückkehr zu Gott) genannt; al-Barāʾ ibn ʿĀzib nannte den letzten Vers von an-Nisāʾ und Barāʾa als letzte vollständige Sure", "ʿUmar nannte Sure al-Fātiḥa und al-Barāʾ nannte al-Iḫlāṣ", "Alle Gefährten waren sich allein über 2:281 einig", "Alle nannten Sure an-Naṣr als einen Vers"], "Die Quellen bewahren mehrere Aussagen. Ibn ʿAbbās wird für 2:281 zitiert (nach einem Bericht der letzte vor dem Tod des Propheten, etwa neun Nächte davor); al-Barāʾ für 4:176 als letzten Vers und Barāʾa als letzte vollständige Sure (al-Buḫārī). Die Gelehrten gleichen sie aus, indem sie jede als ‚letzte‘ zu einem bestimmten Thema oder nach dem Wissen des Erzählers nehmen."],
    ar: ["تذكر الروايات آخر آية أو سورة نزلت. أي عبارة تقرن الروايات برواتها على الوجه الصحيح؟", ["يُروى عن ابن عباس أنها الآية المعروضة (في الاتقاء من يوم الرجوع إلى الله)، وعن البراء بن عازب آخر آية في النساء وأن براءة آخر سورة نزلت كاملة", "ذكر عمر سورة الفاتحة وذكر البراء الإخلاص", "اتفق الصحابة على 2:281 وحدها", "ذكروا جميعًا سورة النصر آيةً"], "تحفظ المصادر عدة أقوال: عن ابن عباس أنها البقرة 281 (في رواية آخر ما نزل قبل وفاة النبي ﷺ بنحو تسع ليال)، وعن البراء النساء 176 آخر آية وبراءة آخر سورة كاملة (البخاري)، ويجمع العلماء بينها بأن كلًّا آخر في موضوع معين أو بحسب علم الراوي."] },

  { id: "xul-025", s: "ulum", g: 4, d: 7, t: ["chronology", "first-revealed"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Badʾ al-Waḥy and Kitāb al-Tafsīr; Ibn Ḥajar, Fatḥ al-Bārī; al-Suyūṭī, al-Itqān, naw‘ 3",
    en: ["How do most scholars reconcile ʿĀʾisha’s report that the first revelation was ‘Read!’ with Jābir’s report that al-Muddaththir was first?", ["‘Read!’ was the first revelation overall, and al-Muddaththir the first after the interval (fatra) in revelation, or the first revealed for the call to warn", "Al-Muddaththir was the first revelation and ‘Read!’ the second, and ʿĀʾisha’s report is rejected", "The two reports describe different prophets", "Both refer to the first verse of al-Fātiḥa"], "Ibn Ḥajar and others say that Jābir’s narration, which has the Prophet describing the angel appearing again after a pause, refers to what came after the interval, and not the very first revelation, which is the beginning of Sūrat al-ʿAlaq as in ʿĀʾisha’s report. This is the majority harmonisation; other views place al-Fātiḥa or al-Muzzammil first."],
    de: ["Wie gleichen die meisten Gelehrten ʿĀʾišas Bericht, die erste Offenbarung sei ‚Lies!‘ gewesen, mit Ǧābirs Bericht, al-Muddaṯṯir sei die erste gewesen, aus?", ["‚Lies!‘ war die erste Offenbarung überhaupt, und al-Muddaṯṯir die erste nach der Pause (fatra) der Offenbarung, bzw. die erste zum Ruf, zu warnen", "Al-Muddaṯṯir war die erste Offenbarung und ‚Lies!‘ die zweite, und ʿĀʾišas Bericht wird verworfen", "Die beiden Berichte beschreiben verschiedene Propheten", "Beide beziehen sich auf den ersten Vers von al-Fātiḥa"], "Ibn Ḥaǧar und andere sagen, Ǧābirs Überlieferung, in der der Prophet beschreibt, wie der Engel nach einer Pause wieder erscheint, beziehe sich auf das, was nach der Pause kam, und nicht auf die allererste Offenbarung, die der Anfang der Sure al-ʿAlaq ist, wie in ʿĀʾišas Bericht. Das ist die Ausgleichung der Mehrheit; andere Ansichten setzen al-Fātiḥa oder al-Muzzammil an die erste Stelle."],
    ar: ["كيف يوفّق أكثر العلماء بين رواية عائشة أن أول ما نزل «اقرأ» ورواية جابر أن المدثر أول ما نزل؟", ["«اقرأ» أول ما نزل مطلقًا، والمدثر أول ما نزل بعد فترة الوحي أو أول ما نزل في أمر الإنذار", "المدثر أول ما نزل و«اقرأ» الثانية وتُرد رواية عائشة", "الروايتان تصفان نبيّين مختلفين", "كلتاهما تشيران إلى أول آية من الفاتحة"], "قال ابن حجر وغيره إن حديث جابر الذي يصف فيه النبي ﷺ ظهور الملك بعد فترة يتعلق بما نزل بعد الفترة لا بأول نزول مطلقًا وهو صدر سورة العلق كما في رواية عائشة، وهذا توفيق الجمهور، وقيل غير ذلك كالفاتحة أو المزمل."] },

  { id: "xul-026", s: "ulum", g: 4, d: 6, t: ["muhkam-mutashabih", "quran-description"], src: "al-Suyūṭī, al-Itqān, naw‘ 43 (al-muḥkam wa-l-mutashābih); al-Zarkashī, al-Burhān; al-Ṭabarī, Jāmiʿ al-Bayān", v: "39:23", w: 6,
    en: ["The verse shown calls the whole Quran mutashābih (alike), while 3:7 divides it into muḥkam and mutashābih verses. How do scholars reconcile these?", ["The Quran is muḥkam in the sense of being precise and flawless (11:1), mutashābih in the sense of its parts resembling one another in excellence (39:23), and in 3:7 mutashābih means the verses whose meaning is not immediately clear", "They are contradictory and one is abrogated", "Both words have exactly the same meaning in all three verses", "Only the Torah is muḥkam, the Quran is mutashābih"], "Al-Suyūṭī gives three states: the whole Quran is muḥkam (perfected and without flaw), it is wholly mutashābih (the parts agree with each other in beauty and truth), and in 3:7 it is divided into verses that are clear and others that need reference to the clear. The wording in each verse is different, hence no conflict."],
    de: ["Der gezeigte Vers nennt den ganzen Koran mutashābih (gleichartig), während 3:7 ihn in muḥkam- und mutashābih-Verse teilt. Wie gleichen Gelehrte das aus?", ["Der Koran ist muḥkam im Sinn von genau und fehlerlos (11:1), mutashābih im Sinn der gegenseitigen Ähnlichkeit seiner Teile an Vortrefflichkeit (39:23), und in 3:7 bedeutet mutashābih die Verse, deren Sinn nicht unmittelbar klar ist", "Sie widersprechen sich, und einer ist aufgehoben", "Beide Wörter haben in allen drei Versen genau dieselbe Bedeutung", "Nur die Tora ist muḥkam, der Koran ist mutashābih"], "As-Suyūṭī nennt drei Zustände: Der ganze Koran ist muḥkam (vervollkommnet und ohne Mangel), er ist ganz mutashābih (die Teile stimmen in Schönheit und Wahrheit miteinander überein), und in 3:7 ist er in klare Verse und andere geteilt, die der Rückbindung an die klaren bedürfen. Der Wortlaut ist in jedem Vers anders, daher kein Widerspruch."],
    ar: ["الآية المعروضة تصف القرآن كله بأنه متشابه، بينما تقسمه آل عمران 7 إلى محكم ومتشابه. كيف يجمع العلماء بين ذلك؟", ["القرآن محكم بمعنى الإتقان وخلوه من الخلل (هود 1)، ومتشابه بمعنى تشابه أجزائه في الحسن (الزمر 23)، والمتشابه في آل عمران 7 ما لا يتضح معناه ابتداءً", "هما متعارضان وأحدهما منسوخ", "للفظين المعنى نفسه في الآيات الثلاث", "المحكم التوراة وحدها والقرآن متشابه"], "ذكر السيوطي ثلاثة أحوال: القرآن كله محكم أي متقن لا خلل فيه، وكله متشابه أي يشبه بعضه بعضًا حسنًا وصدقًا، وفي آل عمران 7 ينقسم إلى محكم واضح ومتشابه يحتاج إلى ردّه إلى المحكم. ومعنى كل لفظ يختلف بحسب الآية فلا تعارض."] },

  { id: "xul-027", s: "ulum", g: 4, d: 6, t: ["terminology", "sura-etymology"], src: "al-Suyūṭī, al-Itqān, naw‘ 17 (ʿadad suwar al-Qurʾān); al-Zarkashī, al-Burhān; Ibn Manẓūr, Lisān al-ʿArab, entry sūr",
    en: ["Which two origins do lexicographers and scholars of the Quranic sciences give for the word sūra?", ["From sūr, an enclosure or wall of a city, because the sūra encloses its verses; or from sūra without hamza, meaning rank or high degree", "From sawr, a bull, or from sūra, a picture", "From Hebrew and from Persian only", "From siyāra, a caravan, or from sūd, a flock"], "The word may be taken as sūr (like the enclosure of a town), since each sūra encloses a set of verses, or as sūra in the sense of a high rank, since its verses are raised above others. Both senses are listed and one need not exclude the other. The word is used for the sūras of the Quran in the Quran itself (24:1; 10:38)."],
    de: ["Welche zwei Herkünfte nennen Lexikographen und Gelehrte der Koranwissenschaften für das Wort sūra?", ["Von sūr, einer Umfriedung oder Stadtmauer, weil die Sure ihre Verse umschließt; oder von sūra ohne Hamza mit der Bedeutung Rang oder hohe Stufe", "Von sawr, Stier, oder von ṣūra, Bild", "Nur aus dem Hebräischen und dem Persischen", "Von siyāra, Karawane, oder von sūd, Herde"], "Das Wort kann als sūr (wie die Umfriedung einer Stadt) genommen werden, da jede Sure eine Reihe von Versen umschließt, oder als sūra im Sinn eines hohen Rangs, da ihre Verse über andere erhoben sind. Beide Bedeutungen werden aufgeführt, und die eine schließt die andere nicht aus. Das Wort wird im Koran selbst für die Suren des Korans gebraucht (24:1; 10:38)."],
    ar: ["ما الأصلان اللذان يذكرهما اللغويون وعلماء علوم القرآن للفظ «سورة»؟", ["من السور وهو سور المدينة لأن السورة تحيط بآياتها، أو من السورة بلا همز بمعنى المنزلة الرفيعة", "من الثور أو من الصورة", "من العبرية والفارسية فقط", "من السيارة أو من السرب"], "يجوز أن يُراد بالسورة سور المدينة لأنها تحوط مجموعة من الآيات، أو المنزلة الرفيعة لارتفاع آياتها على غيرها، ولا يمنع أحد الأصلين الآخر، وقد استُعمل اللفظ في القرآن نفسه للسور (النور 1، يونس 38)."] },

  { id: "xul-028", s: "ulum", g: 4, d: 7, t: ["divisions", "manazil"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṣalāh (the hadith of Aws ibn Ḥudhayfa); Ibn Ḥajar, Fatḥ al-Bārī; al-Suyūṭī, al-Itqān",
    en: ["What are the seven manāzil of the Quran, associated with the mnemonic ‘fa-mī bi-shawq’?", ["Seven divisions beginning with the sūras al-Fātiḥa, al-Māʾida, Yūnus, al-Isrāʾ, al-Shuʿarāʾ, al-Ṣāffāt and Qāf", "Seven divisions beginning with al-Baqara, Āl ʿImrān, al-Nisāʾ, al-Māʾida, al-Anʿām, al-Aʿrāf and al-Anfāl", "Seven divisions of equal length of 30 sūras each", "Seven divisions by the seven readers"], "The mnemonic gives the first letters of the opening sūras of the seven daily portions (fā for al-Fātiḥa, mīm for al-Māʾida, yāʾ for Yūnus, bāʾ for Banī Isrāʾīl, shīn for al-Shuʿarāʾ, wāw for al-Ṣāffāt, qāf for Qāf), according to a report from Aws ibn Ḥudhayfa that the Companions divided the Quran this way for a weekly recitation."],
    de: ["Was sind die sieben Manāzil des Korans, verbunden mit der Merkformel ‚fa-mī bi-shawq‘?", ["Sieben Abschnitte, die mit den Suren al-Fātiḥa, al-Māʾida, Yūnus, al-Isrāʾ, aš-Šuʿarāʾ, aṣ-Ṣāffāt und Qāf beginnen", "Sieben Abschnitte, die mit al-Baqara, Āl ʿImrān, an-Nisāʾ, al-Māʾida, al-Anʿām, al-Aʿrāf und al-Anfāl beginnen", "Sieben gleich lange Abschnitte von je 30 Suren", "Sieben Abschnitte nach den sieben Lesern"], "Die Merkformel nennt die Anfangsbuchstaben der Eröffnungssuren der sieben Tagesabschnitte (fā für al-Fātiḥa, mīm für al-Māʾida, yāʾ für Yūnus, bāʾ für Banī Isrāʾīl, šīn für aš-Šuʿarāʾ, wāw für aṣ-Ṣāffāt, qāf für Qāf), nach einem Bericht von Aws ibn Ḥuḏaifa, dass die Gefährten den Koran für eine wöchentliche Rezitation so einteilten."],
    ar: ["ما المنازل السبع للقرآن المرتبطة بعبارة «فمي بشوق»؟", ["سبعة أقسام تبدأ بسور الفاتحة والمائدة ويونس والإسراء والشعراء والصافات وق", "سبعة أقسام تبدأ بالبقرة وآل عمران والنساء والمائدة والأنعام والأعراف والأنفال", "سبعة أقسام متساوية الطول من ثلاثين سورة لكل منها", "سبعة أقسام بحسب القراء السبعة"], "تجمع العبارة الأحرف الأولى من السور التي تبدأ بها منازل الأسبوع السبعة (الفاء للفاتحة والميم للمائدة والياء ليونس والباء لبني إسرائيل والشين للشعراء والواو للصافات والقاف لق)، وقد رُوي عن أوس بن حذيفة أن الصحابة قسموا القرآن كذلك للختم في أسبوع."] },

  { id: "xul-029", s: "ulum", g: 4, d: 7, t: ["divisions", "tiwal"], src: "al-Suyūṭī, al-Itqān, naw‘ 17; Aḥmad ibn Ḥanbal, Musnad (hadith of Wāthila ibn al-Asqaʿ); al-Zarkashī, al-Burhān",
    en: ["Which sūras make up the ‘seven long ones’ (al-sabʿ al-ṭiwal), and what is disputed about them?", ["al-Baqara, Āl ʿImrān, al-Nisāʾ, al-Māʾida, al-Anʿām, al-Aʿrāf and a seventh disputed between Yūnus and al-Anfāl with al-Tawba taken together", "al-Fātiḥa, al-Baqara, Yūsuf, al-Kahf, Maryam, Ṭā Hā and al-Ikhlāṣ", "The seven longest sūras in Makkan revelation only", "al-Ṣāffāt to Qāf"], "A report associated with Wāthila ibn al-Asqaʿ lists the ṭiwāl, the miʾūn, the mathānī and the mufaṣṣal. The first six of the long ones are agreed; the seventh is either Yūnus or al-Anfāl with Barāʾa treated as one (the reason why there is no basmala between them). The division belongs to the early classification of the Quran by length."],
    de: ["Welche Suren bilden die ‚sieben langen‘ (as-sabʿ aṭ-ṭiwāl), und was ist daran umstritten?", ["Al-Baqara, Āl ʿImrān, an-Nisāʾ, al-Māʾida, al-Anʿām, al-Aʿrāf und eine siebte, umstritten zwischen Yūnus und al-Anfāl zusammen mit at-Tawba", "Al-Fātiḥa, al-Baqara, Yūsuf, al-Kahf, Maryam, Ṭā Hā und al-Iḫlāṣ", "Die sieben längsten Suren allein der mekkanischen Offenbarung", "Aṣ-Ṣāffāt bis Qāf"], "Ein mit Wāṯila ibn al-Asqaʿ verbundener Bericht nennt die Ṭiwāl, die Miʾūn, die Maṯānī und das Mufaṣṣal. Die ersten sechs der langen sind unstrittig; die siebte ist entweder Yūnus oder al-Anfāl mit Barāʾa als eine Einheit (der Grund, warum zwischen ihnen keine Basmala steht). Die Einteilung gehört zur frühen Klassifikation des Korans nach Länge."],
    ar: ["ما السور التي تكوّن «السبع الطوال» وما المختلف فيه منها؟", ["البقرة وآل عمران والنساء والمائدة والأنعام والأعراف، والسابعة مختلف فيها بين يونس والأنفال مع التوبة معًا", "الفاتحة والبقرة ويوسف والكهف ومريم وطه والإخلاص", "أطول سبع سور في الوحي المكي فقط", "من الصافات إلى ق"], "تذكر رواية تُنسب إلى واثلة بن الأسقع الطوال والمئين والمثاني والمفصل، والست الأولى من الطوال متفق عليها والسابعة إما يونس أو الأنفال مع براءة على أنهما واحدة (ولذلك لا بسملة بينهما)، والتقسيم من التصنيف المبكر للقرآن بحسب الطول."] },

  { id: "xul-030", s: "ulum", g: 4, d: 6, t: ["verse-counting", "kufan-count"], src: "al-Dānī, al-Bayān fī ʿAdd Āy al-Qurʾān; al-Suyūṭī, al-Itqān, naw‘ 17",
    en: ["Which verse count is followed by the standard Ḥafṣ muṣḥaf, and what total does it give?", ["The Kufan count, with 6,236 verses; it numbers the basmala of al-Fātiḥa as a verse", "The Madinan count, with 6,000 verses exactly", "The Basran count, with 6,666 verses", "The Syrian count, with 6,100 verses"], "The Kufan count, traced through Abū ʿAbd al-Raḥmān al-Sulamī to ʿAlī, is used in the common Ḥafṣ muṣḥaf and totals 6,236. In this count the basmala is a verse of al-Fātiḥa. Other cities count slightly differently, as the Madinan, Makkan, Syrian and Basran counts. The figure of 6,666 is popular but not a count of any city."],
    de: ["Welche Verszählung folgt der übliche Ḥafṣ-Muṣḥaf, und welche Gesamtzahl ergibt sie?", ["Die kufische Zählung mit 6236 Versen; sie zählt die Basmala von al-Fātiḥa als Vers", "Die medinensische Zählung mit genau 6000 Versen", "Die basrische Zählung mit 6666 Versen", "Die syrische Zählung mit 6100 Versen"], "Die kufische Zählung, über Abū ʿAbd ar-Raḥmān as-Sulamī auf ʿAlī zurückgeführt, wird im üblichen Ḥafṣ-Muṣḥaf verwendet und ergibt 6236. In dieser Zählung ist die Basmala ein Vers von al-Fātiḥa. Andere Städte zählen leicht anders, wie die medinensische, mekkanische, syrische und basrische Zählung. Die Zahl 6666 ist beliebt, aber keine Zählung einer Stadt."],
    ar: ["أي عدٍّ للآيات يتبعه المصحف المعتاد برواية حفص وما مجموعه؟", ["العدّ الكوفي ومجموعه 6236 آية ويعدّ البسملة آية من الفاتحة", "العدّ المدني ومجموعه 6000 آية بالضبط", "العدّ البصري ومجموعه 6666 آية", "العدّ الشامي ومجموعه 6100 آية"], "العدّ الكوفي المسند عن أبي عبد الرحمن السلمي عن علي هو المتبع في المصحف المعتاد برواية حفص ومجموعه 6236، وفيه تُعدّ البسملة آية من الفاتحة، وللمدينة ومكة والشام والبصرة أعداد تختلف يسيرًا، أما رقم 6666 فشائع لكنه ليس عدّ مصر من الأمصار."] },

  { id: "xul-031", s: "ulum", g: 4, d: 6, t: ["muqattaat", "counts"], src: "al-Suyūṭī, al-Itqān, naw‘ 43 (fawātiḥ al-suwar); al-Zarkashī, al-Burhān, naw‘ 18",
    en: ["How many sūras begin with the disjointed letters (al-ḥurūf al-muqaṭṭaʿa), and how many different letters occur?", ["Twenty-nine sūras; fourteen different letters, half of the Arabic alphabet", "Twenty sūras; ten letters", "Forty sūras; twenty letters", "Twelve sūras; seven letters"], "The classical works count twenty-nine sūras with such openings, using fourteen different letters, which is half of the twenty-eight letters of the alphabet. Some openings are one letter (ṣād, qāf, nūn), others two to five letters. Al-Suyūṭī and al-Zarkashī discuss the many views on their meaning."],
    de: ["Wie viele Suren beginnen mit den abgesetzten Buchstaben (al-ḥurūf al-muqaṭṭaʿa), und wie viele verschiedene Buchstaben kommen vor?", ["Neunundzwanzig Suren; vierzehn verschiedene Buchstaben, die Hälfte des arabischen Alphabets", "Zwanzig Suren; zehn Buchstaben", "Vierzig Suren; zwanzig Buchstaben", "Zwölf Suren; sieben Buchstaben"], "Die klassischen Werke zählen neunundzwanzig Suren mit solchen Anfängen, die vierzehn verschiedene Buchstaben verwenden, also die Hälfte der achtundzwanzig Buchstaben des Alphabets. Manche Anfänge bestehen aus einem Buchstaben (Ṣād, Qāf, Nūn), andere aus zwei bis fünf. As-Suyūṭī und az-Zarkašī erörtern die vielen Ansichten über ihre Bedeutung."],
    ar: ["كم سورة تبدأ بالحروف المقطعة وكم حرفًا مختلفًا يرد فيها؟", ["تسع وعشرون سورة وأربعة عشر حرفًا مختلفًا أي نصف حروف الهجاء", "عشرون سورة وعشرة حروف", "أربعون سورة وعشرون حرفًا", "اثنتا عشرة سورة وسبعة حروف"], "تعدّ الكتب القديمة تسعًا وعشرين سورة افتتحت بهذه الحروف، والحروف المختلفة فيها أربعة عشر وهي نصف حروف الهجاء الثمانية والعشرين، بعضها حرف واحد (ص ق ن) وبعضها من اثنين إلى خمسة، ويناقش السيوطي والزركشي الأقوال الكثيرة في معناها."] },

  { id: "xul-032", s: "ulum", g: 4, d: 7, t: ["muqattaat", "views"], tr: ["comparative"], src: "al-Zamakhsharī, al-Kashshāf, on Sūrat al-Baqara; Ibn Taymiyya, Majmūʿ al-Fatāwā; al-Suyūṭī, al-Itqān, naw‘ 43",
    en: ["Which view on the disjointed letters is associated with al-Zamakhsharī and, in a related form, with Ibn Taymiyya?", ["That they are a pointer to the inimitability: the Quran is made of the same letters as the Arabs’ speech, yet they could not produce the like", "That they are the secret known to God alone, so nothing can be said about them", "That they are the names of the angels", "That they are the initials of the transmitters"], "Among the views are: secrets known only to God (Abū Bakr, ʿAlī and Ibn Masʿūd, in reports); names of sūras; oaths; names of God; and an allusion to the challenge. Al-Zamakhsharī, following some earlier grammarians, took them as showing that the Quran is composed of ordinary letters and yet inimitable; Ibn Taymiyya supports this reading for most openings. The scholars of the schools avoid certainty."],
    de: ["Welche Ansicht zu den abgesetzten Buchstaben wird mit az-Zamaḫšarī und in verwandter Form mit Ibn Taimiyya verbunden?", ["Dass sie ein Hinweis auf die Unnachahmlichkeit sind: Der Koran besteht aus denselben Buchstaben wie die Rede der Araber, doch sie konnten nichts Gleiches hervorbringen", "Dass sie das nur Gott bekannte Geheimnis sind, über das nichts gesagt werden kann", "Dass sie die Namen der Engel sind", "Dass sie die Anfangsbuchstaben der Überlieferer sind"], "Zu den Ansichten gehören: nur Gott bekannte Geheimnisse (Abū Bakr, ʿAlī und Ibn Masʿūd nach Berichten); Namen von Suren; Schwüre; Namen Gottes; und eine Anspielung auf die Herausforderung. Az-Zamaḫšarī nahm sie, einigen früheren Grammatikern folgend, als Hinweis darauf, dass der Koran aus gewöhnlichen Buchstaben besteht und doch unnachahmlich ist; Ibn Taimiyya stützt diese Lesung für die meisten Anfänge. Die Gelehrten der Schulen vermeiden Gewissheit."],
    ar: ["أي رأي في الحروف المقطعة يُنسب إلى الزمخشري وإلى ابن تيمية في صورة قريبة منه؟", ["أنها إشارة إلى الإعجاز: القرآن مؤلف من حروف كلام العرب نفسها ومع ذلك عجزوا عن مثله", "أنها سر لا يعلمه إلا الله فلا يُقال فيها شيء", "أنها أسماء الملائكة", "أنها رموز لأسماء الرواة"], "من الأقوال أنها من المتشابه الذي استأثر الله بعلمه (ويُروى عن أبي بكر وعلي وابن مسعود)، وأسماء للسور، وأقسام، وأسماء لله، وإشارة إلى التحدي. وذهب الزمخشري تبعًا لبعض النحاة إلى أنها تبيّن أن القرآن من حروف عادية وهو معجز، ويؤيد ابن تيمية هذا في أكثر الفواتح، ويتحرز علماء المذاهب من الجزم."] },

  { id: "xul-033", s: "ulum", g: 4, d: 6, t: ["classical-works", "ibn-qutayba"], src: "Ibn Qutayba, Taʾwīl Mushkil al-Qurʾān; Ibn Qutayba, Gharīb al-Qurʾān",
    en: ["What is Ibn Qutayba’s Taʾwīl Mushkil al-Qurʾān?", ["A defence of the Quran against alleged contradictions and difficulties in language and meaning, with a study of figurative usage", "A collection of the occasions of revelation", "A work of tajwīd for beginners", "A history of the Companions"], "Ibn Qutayba (d. 276 AH) wrote this work in reply to those who found contradiction or errors in the Quran, discussing figurative usage, rare words, variant readings and apparent contradictions with the aid of Arabic poetry and usage. It is a foundation for the later literature on mushkil al-Qurʾān. His Gharīb al-Qurʾān is a separate book of rare words."],
    de: ["Was ist Ibn Qutaibas Taʾwīl Muškil al-Qurʾān?", ["Eine Verteidigung des Korans gegen angebliche Widersprüche und Schwierigkeiten in Sprache und Bedeutung, mit einer Untersuchung des übertragenen Gebrauchs", "Eine Sammlung der Offenbarungsanlässe", "Ein Tağwīd-Werk für Anfänger", "Eine Geschichte der Gefährten"], "Ibn Qutaiba (gest. 276 n. H.) schrieb dieses Werk als Antwort auf diejenigen, die im Koran Widersprüche oder Fehler fanden, und erörtert mithilfe arabischer Dichtung und arabischen Sprachgebrauchs den übertragenen Gebrauch, seltene Wörter, Lesartvarianten und scheinbare Widersprüche. Es ist eine Grundlage der späteren Literatur über Muškil al-Qurʾān. Sein Ġarīb al-Qurʾān ist ein eigenes Buch über seltene Wörter."],
    ar: ["ما كتاب «تأويل مشكل القرآن» لابن قتيبة؟", ["دفاع عن القرآن ضد ما يُزعم فيه من تناقض وإشكال في اللغة والمعنى مع دراسة للأساليب المجازية", "مجموعة من أسباب النزول", "كتاب تجويد للمبتدئين", "تاريخ للصحابة"], "ألّف ابن قتيبة (ت 276هـ) هذا الكتاب ردًّا على من زعموا في القرآن تناقضًا أو خطأ، فبحث المجاز والألفاظ الغريبة والقراءات والتعارض الظاهري مستعينًا بالشعر العربي وأساليب العرب، وهو أساس لما كُتب بعده في مشكل القرآن. أما «غريب القرآن» فكتاب مستقل في الألفاظ الغريبة."] },

  { id: "xul-034", s: "ulum", g: 4, d: 7, t: ["revelation", "descent-of-quran"], tr: ["comparative"], src: "al-Suyūṭī, al-Itqān, naw‘ 16 (kayfiyyat inzāl al-Qurʾān); al-Ṭabarī, Jāmiʿ al-Bayān, on 2:185; al-Zarkashī, al-Burhān",
    en: ["Which account of the descent of the Quran is reported from Ibn ʿAbbās and favoured by many scholars?", ["It came down all at once to the lowest heaven on Laylat al-Qadr, then was revealed in parts to the Prophet over about twenty-three years", "It came down in parts only, with no earlier stage", "It was first revealed in Madīna", "It was revealed all at once to the Prophet on Laylat al-Qadr"], "In the reports from Ibn ʿAbbās, the Quran was sent down as a whole to bayt al-ʿizza in the lowest heaven, and then to the Prophet gradually as events required. Al-Shaʿbī and others said the revelation began on Laylat al-Qadr and then continued. Both views explain the verse mentioning the month in which the Quran was sent down."],
    de: ["Welche Darstellung der Herabsendung des Korans wird von Ibn ʿAbbās berichtet und von vielen Gelehrten bevorzugt?", ["Er wurde auf einmal zum untersten Himmel herabgesandt in der Nacht der Bestimmung, dann in Teilen dem Propheten über etwa dreiundzwanzig Jahre offenbart", "Er kam nur in Teilen herab, ohne früheres Stadium", "Er wurde zuerst in Medina offenbart", "Er wurde dem Propheten in der Nacht der Bestimmung auf einmal offenbart"], "In den Berichten von Ibn ʿAbbās wurde der Koran als Ganzes in das Bait al-ʿIzza im untersten Himmel herabgesandt und dann dem Propheten schrittweise, wie die Ereignisse es erforderten. Aš-Šaʿbī und andere sagten, die Offenbarung habe in der Nacht der Bestimmung begonnen und sei dann fortgesetzt worden. Beide Ansichten erklären den Vers, der den Monat nennt, in dem der Koran herabgesandt wurde."],
    ar: ["أي تصوير لنزول القرآن يُروى عن ابن عباس ويرجحه كثير من العلماء؟", ["نزل جملة واحدة إلى السماء الدنيا ليلة القدر ثم نزل منجمًا على النبي ﷺ في نحو ثلاث وعشرين سنة", "نزل منجمًا فقط بلا مرحلة سابقة", "نزل أول ما نزل في المدينة", "نزل على النبي ﷺ جملة واحدة ليلة القدر"], "في الروايات عن ابن عباس أن القرآن أُنزل كله إلى بيت العزة في السماء الدنيا ثم نزل على النبي ﷺ مفرقًا بحسب الحوادث، وقال الشعبي وغيره إن ابتداء النزول كان ليلة القدر ثم تتابع، والقولان يفسران الآية التي تذكر الشهر الذي أنزل فيه القرآن."] },

  { id: "xul-035", s: "ulum", g: 4, d: 7, t: ["compilation", "basmala"], tr: ["comparative"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṣalāh (bāb man jahara bi-hā); al-Tirmidhī, Jāmiʿ, Kitāb al-Tafsīr (Sūrat al-Tawba); al-Suyūṭī, al-Itqān, naw‘ 17",
    en: ["What reason did ʿUthmān give, in the report preserved in Abū Dāwūd and al-Tirmidhī, for placing al-Anfāl and Barāʾa together without a basmala between them?", ["Barāʾa resembled al-Anfāl in its subject, and the Prophet died without having said whether it was part of it, so he joined them without a basmala", "The Prophet explicitly ordered that no basmala be written", "The two sūras had been revealed at the same hour", "The scribes ran out of space"], "Ibn ʿAbbās asked ʿUthmān why he placed al-Anfāl (among the early Madinan sūras) next to Barāʾa (among the last), without a basmala. He replied that the Prophet died without explaining Barāʾa, and that its story resembled that of al-Anfāl, so he considered it part of it. Others explain that the Companions did not write a basmala at the start of Barāʾa because of its theme of severing treaties."],
    de: ["Welchen Grund nannte ʿUṯmān im bei Abū Dāwūd und at-Tirmiḏī bewahrten Bericht dafür, al-Anfāl und Barāʾa ohne Basmala dazwischen zusammenzustellen?", ["Barāʾa ähnelte al-Anfāl im Gegenstand, und der Prophet starb, ohne gesagt zu haben, ob sie dazugehörte, daher fügte er sie ohne Basmala zusammen", "Der Prophet ordnete ausdrücklich an, keine Basmala zu schreiben", "Die beiden Suren wurden zur selben Stunde offenbart", "Den Schreibern ging der Platz aus"], "Ibn ʿAbbās fragte ʿUṯmān, warum er al-Anfāl (unter den frühen medinensischen Suren) neben Barāʾa (unter den letzten) ohne Basmala gestellt habe. Er antwortete, der Prophet sei gestorben, ohne Barāʾa zu erläutern, und ihre Geschichte ähnle der von al-Anfāl, daher habe er sie für einen Teil davon gehalten. Andere erklären, die Gefährten hätten zu Beginn von Barāʾa wegen ihres Themas der Aufkündigung von Verträgen keine Basmala geschrieben."],
    ar: ["ما السبب الذي ذكره عثمان في الرواية المحفوظة عند أبي داود والترمذي لجمع الأنفال وبراءة دون بسملة بينهما؟", ["أن براءة تشبه الأنفال في موضوعها وقُبض النبي ﷺ ولم يبيّن أنها منها فجمعهما بلا بسملة", "أن النبي ﷺ أمر صراحةً بترك البسملة", "أن السورتين نزلتا في ساعة واحدة", "أن الكتبة نفد عندهم المكان"], "سأل ابن عباس عثمان لماذا جعل الأنفال وهي من أوائل المدني بجانب براءة وهي من آخره دون بسملة، فأجاب بأن النبي ﷺ قُبض ولم يبيّن أمر براءة وأن قصتها تشبه قصة الأنفال فظنها منها. وقيل في سبب ترك البسملة غير ذلك كموضوع نقض العهود."] },

  { id: "xul-036", s: "ulum", g: 4, d: 6, t: ["basmala", "fiqh-and-ulum"], tr: ["shafii", "maliki", "hanafi", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāh (basmala in the Fātiḥa); al-Suyūṭī, al-Itqān, naw‘ 17; al-Nawawī, al-Majmūʿ",
    en: ["Which statement correctly describes the views of the schools on whether the basmala is a verse of al-Fātiḥa?", ["The Shāfiʿīs count it as a verse of al-Fātiḥa, whereas the Mālikīs do not count it as a verse of al-Fātiḥa or of any sūra other than al-Naml", "All schools count it as a verse of every sūra", "All schools deny it is a part of any sūra", "The Ḥanafīs say it is a part of al-Fātiḥa, the Shāfiʿīs deny it"], "The Shāfiʿīs and the Kufan and Makkan counts treat the basmala as a verse of al-Fātiḥa (and, in one view, of every sūra), so they recite it in prayer. The Mālikīs hold it is not a verse of al-Fātiḥa or of the other sūras, but part of al-Naml (27:30); the Ḥanafīs hold it a verse of the Quran revealed to separate the sūras. The difference lies behind their practice of reciting it aloud or silently."],
    de: ["Welche Aussage beschreibt die Ansichten der Schulen zur Frage, ob die Basmala ein Vers von al-Fātiḥa ist, richtig?", ["Die Schafiiten zählen sie als Vers von al-Fātiḥa, während die Malikiten sie weder als Vers von al-Fātiḥa noch einer anderen Sure außer an-Naml zählen", "Alle Schulen zählen sie als Vers jeder Sure", "Alle Schulen bestreiten, dass sie Teil irgendeiner Sure ist", "Die Hanafiten sagen, sie sei Teil von al-Fātiḥa, die Schafiiten bestreiten es"], "Die Schafiiten sowie die kufische und mekkanische Zählung behandeln die Basmala als Vers von al-Fātiḥa (und nach einer Ansicht jeder Sure), sodass sie sie im Gebet rezitieren. Die Malikiten halten sie weder für einen Vers von al-Fātiḥa noch der anderen Suren, wohl aber für einen Teil von an-Naml (27:30); die Hanafiten halten sie für einen Vers des Korans, der zur Trennung der Suren offenbart wurde. Der Unterschied liegt ihrer Praxis zugrunde, sie laut oder leise zu rezitieren."],
    ar: ["أي عبارة تصف مواقف المذاهب على الوجه الصحيح في كون البسملة آية من الفاتحة؟", ["الشافعية يعدّونها آية من الفاتحة، والمالكية لا يعدّونها آية من الفاتحة ولا من غيرها إلا في النمل", "المذاهب كلها تعدّها آية من كل سورة", "المذاهب كلها تنفي أن تكون جزءًا من أي سورة", "الحنفية يقولون إنها جزء من الفاتحة والشافعية تنفي"], "الشافعية وعدّ أهل الكوفة ومكة يعدّون البسملة آية من الفاتحة (وفي قول من كل سورة) فيقرؤونها في الصلاة، والمالكية على أنها ليست آية من الفاتحة ولا من غيرها وإنما هي من النمل 30، والحنفية على أنها آية من القرآن أُنزلت للفصل بين السور. وهذا الاختلاف وراء جهرهم بها أو إسرارهم."] },

  { id: "xul-037", s: "ulum", g: 4, d: 7, t: ["compilation", "order-of-surahs"], tr: ["comparative"], src: "al-Suyūṭī, al-Itqān, naw‘ 18 (tartīb al-āyāt wa-l-suwar); al-Zarkashī, al-Burhān; al-Bāqillānī, al-Intiṣār li-l-Qurʾān",
    en: ["What do the classical works record on whether the order of the verses and of the sūras in the muṣḥaf is divinely fixed (tawqīfī)?", ["The order of the verses within each sūra is tawqīfī by consensus; for the order of the sūras there are three views: tawqīfī, the Companions’ ijtihād, or a mixture", "Both orders were decided by ʿUthmān alone with no precedent", "Both orders were settled by a vote of the Companions", "Both orders follow the order of revelation exactly"], "Al-Suyūṭī records that the arrangement of verses is divinely taught and the scholars agree on it. For the sūras, some say the Prophet arranged them, as shown by his reciting several sūras in order; others, such as Mālik and (in one report) al-Bāqillānī, held that the Companions arranged them by ijtihād; and a third view takes some as taught and some as arranged. The muṣḥaf order is not the order of revelation."],
    de: ["Was verzeichnen die klassischen Werke zur Frage, ob die Reihenfolge der Verse und der Suren im Muṣḥaf göttlich festgelegt (tawqīfī) ist?", ["Die Reihenfolge der Verse innerhalb jeder Sure ist tawqīfī nach Konsens; für die Reihenfolge der Suren gibt es drei Ansichten: tawqīfī, Iǧtihād der Gefährten oder eine Mischung", "Beide Ordnungen bestimmte ʿUṯmān allein ohne Vorbild", "Beide Ordnungen wurden durch eine Abstimmung der Gefährten festgelegt", "Beide Ordnungen folgen genau der Offenbarungsreihenfolge"], "As-Suyūṭī verzeichnet, dass die Anordnung der Verse göttlich gelehrt ist und die Gelehrten sich darin einig sind. Bei den Suren sagen manche, der Prophet habe sie geordnet, wie sein Rezitieren mehrerer Suren hintereinander zeigt; andere wie Mālik und (nach einem Bericht) al-Bāqillānī meinten, die Gefährten hätten sie durch Iǧtihād geordnet; und eine dritte Ansicht nimmt einige als gelehrt und einige als geordnet. Die Muṣḥaf-Ordnung ist nicht die Offenbarungsreihenfolge."],
    ar: ["ماذا تسجل الكتب القديمة في كون ترتيب الآيات والسور في المصحف توقيفيًّا؟", ["ترتيب الآيات في كل سورة توقيفي بالإجماع، وفي ترتيب السور ثلاثة أقوال: توقيفي أو اجتهاد من الصحابة أو مزيج", "رتّب عثمان الترتيبين وحده بلا سابقة", "تقرر الترتيبان بتصويت الصحابة", "الترتيبان يوافقان ترتيب النزول بالضبط"], "ذكر السيوطي أن ترتيب الآيات توقيفي بإجماع العلماء، وفي السور قيل رتبها النبي ﷺ كما يدل قراءته عدة سور متتابعة، وقيل اجتهاد من الصحابة وهو قول مالك وروي عن الباقلاني، وقيل بعضها توقيفي وبعضها اجتهاد. وترتيب المصحف ليس ترتيب النزول."] },

  { id: "xul-038", s: "ulum", g: 4, d: 6, t: ["classical-works", "verse-counting"], src: "al-Dānī, al-Bayān fī ʿAdd Āy al-Qurʾān; al-Suyūṭī, al-Itqān",
    en: ["Who wrote al-Bayān fī ʿAdd Āy al-Qurʾān, the classical work on the counting of the verses by the cities of Islam?", ["Abū ʿAmr al-Dānī", "al-Shāṭibī", "Ibn al-Jazarī", "al-Zarkashī"], "Abū ʿAmr al-Dānī (d. 444 AH) of Dāniya in Spain wrote al-Bayān, which sets out the verse counts transmitted by the people of Madīna, Makka, Kūfa, Baṣra and Shām. Al-Shāṭibī versified other works of his; Ibn al-Jazarī wrote on qirāʾāt, and al-Zarkashī on the sciences of the Quran."],
    de: ["Wer schrieb al-Bayān fī ʿAdd Āy al-Qurʾān, das klassische Werk über die Zählung der Verse in den Städten des Islam?", ["Abū ʿAmr ad-Dānī", "Aš-Šāṭibī", "Ibn al-Ǧazarī", "Az-Zarkašī"], "Abū ʿAmr ad-Dānī (gest. 444 n. H.) aus Dāniya in Spanien schrieb al-Bayān, das die von den Leuten von Medina, Mekka, Kufa, Basra und Syrien überlieferten Verszählungen darlegt. Aš-Šāṭibī versifizierte andere Werke von ihm; Ibn al-Ǧazarī schrieb über Qirāʾāt und az-Zarkašī über die Koranwissenschaften."],
    ar: ["من الذي ألّف «البيان في عدّ آي القرآن» وهو العمل الكلاسيكي في عدّ الآيات بين أمصار الإسلام؟", ["أبو عمرو الداني", "الشاطبي", "ابن الجزري", "الزركشي"], "ألّف أبو عمرو الداني (ت 444هـ) الدانيّ الأندلسي «البيان» وفيه أعداد الآيات المروية عن أهل المدينة ومكة والكوفة والبصرة والشام، ونظم الشاطبي كتبًا أخرى له، وكتب ابن الجزري في القراءات والزركشي في علوم القرآن."] },

  { id: "xul-039", s: "ulum", g: 4, d: 7, t: ["ahruf", "views"], tr: ["comparative"], src: "al-Suyūṭī, al-Itqān, naw‘ 16; Abū ʿUbayd, Faḍāʾil al-Qurʾān; Ibn Qutayba, Taʾwīl Mushkil al-Qurʾān; al-Ṭabarī, Jāmiʿ al-Bayān, introduction",
    en: ["Which scholar is associated with the view that the seven aḥruf are seven dialects of the Arabs, whereas another scholar understood them as seven kinds of difference in the wording?", ["Abū ʿUbayd for the dialects; Ibn Qutayba for the seven kinds of difference", "Ibn Qutayba for the dialects; Abū ʿUbayd for the kinds of difference", "Al-Ṭabarī for the dialects; al-Bāqillānī for the kinds of difference", "Al-Zarkashī for the dialects; al-Suyūṭī for the kinds of difference"], "Abū ʿUbayd al-Qāsim ibn Sallām (d. 224 AH) took the aḥruf as seven dialects of the Arabs, such as Quraysh, Hudhayl and Hawāzin. Ibn Qutayba (d. 276 AH) understood them as seven aspects of differences in the readings (in the form of nouns, verbs, iʿrāb, order, substitution and so on). Al-Suyūṭī lists about forty views."],
    de: ["Welcher Gelehrte wird mit der Ansicht verbunden, die sieben Aḥruf seien sieben Dialekte der Araber, während ein anderer sie als sieben Arten der Wortlautverschiedenheit verstand?", ["Abū ʿUbaid für die Dialekte; Ibn Qutaiba für die sieben Arten der Verschiedenheit", "Ibn Qutaiba für die Dialekte; Abū ʿUbaid für die Arten der Verschiedenheit", "Aṭ-Ṭabarī für die Dialekte; al-Bāqillānī für die Arten der Verschiedenheit", "Az-Zarkašī für die Dialekte; as-Suyūṭī für die Arten der Verschiedenheit"], "Abū ʿUbaid al-Qāsim ibn Sallām (gest. 224 n. H.) nahm die Aḥruf als sieben Dialekte der Araber, etwa Quraiš, Hudhail und Hawāzin. Ibn Qutaiba (gest. 276 n. H.) verstand sie als sieben Aspekte von Unterschieden in den Lesarten (in der Form von Nomen, Verben, Iʿrāb, Wortstellung, Ersetzung usw.). As-Suyūṭī führt rund vierzig Ansichten auf."],
    ar: ["من يُنسب إليه القول بأن الأحرف السبعة سبع لغات من لغات العرب، ومن فهمها وجوهًا سبعة من الاختلاف في اللفظ؟", ["أبو عبيد للغات، وابن قتيبة لوجوه الاختلاف السبعة", "ابن قتيبة للغات، وأبو عبيد لوجوه الاختلاف", "الطبري للغات، والباقلاني لوجوه الاختلاف", "الزركشي للغات، والسيوطي لوجوه الاختلاف"], "ذهب أبو عبيد القاسم بن سلام (ت 224هـ) إلى أن الأحرف سبع لغات من لغات العرب كقريش وهذيل وهوازن، وفهمها ابن قتيبة (ت 276هـ) على أنها سبعة وجوه من الاختلاف في القراءات (في الأسماء والأفعال والإعراب والترتيب والإبدال وغيرها)، وأورد السيوطي نحو أربعين قولًا."] },

  { id: "xul-040", s: "ulum", g: 4, d: 7, t: ["ahruf", "uthmanic-copies"], tr: ["comparative"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, introduction (on the aḥruf and ʿUthmān’s collection); Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr; Abū Shāma, al-Murshid al-Wajīz",
    en: ["Which scholar held that ʿUthmān’s copies preserved a single ḥarf of the seven, and who disagreed?", ["Al-Ṭabarī held that the community was united on a single ḥarf; Ibn al-Jazarī and many others held the copies preserve whatever of the aḥruf was established in the final presentation", "Ibn al-Jazarī held it was a single ḥarf; al-Ṭabarī held all seven", "Abū Shāma held the copies had no ḥarf of the seven", "Both held that the seven aḥruf were written in the copies as separate texts"], "In his introduction al-Ṭabarī argued that the permission to read in seven aḥruf was a facility that ended when ʿUthmān united the community on the single ḥarf of Quraysh in order to prevent strife. Ibn al-Jazarī, Abū Shāma and many later scholars held that the copies include whatever of the aḥruf was established in the final presentation, with the dotless rasm allowing several readings."],
    de: ["Welcher Gelehrte vertrat, ʿUṯmāns Exemplare hätten ein einziges Ḥarf der sieben bewahrt, und wer widersprach?", ["Aṭ-Ṭabarī meinte, die Gemeinschaft sei auf ein einziges Ḥarf vereint worden; Ibn al-Ǧazarī und viele andere meinten, die Exemplare bewahrten, was von den Aḥruf bei der letzten Vorlage feststand", "Ibn al-Ǧazarī meinte, es sei ein einziges Ḥarf gewesen; aṭ-Ṭabarī meinte alle sieben", "Abū Šāma meinte, die Exemplare enthielten kein Ḥarf der sieben", "Beide meinten, die sieben Aḥruf seien in den Exemplaren als getrennte Texte geschrieben"], "In seiner Einleitung argumentierte aṭ-Ṭabarī, die Erlaubnis, in sieben Aḥruf zu lesen, sei eine Erleichterung gewesen, die endete, als ʿUṯmān die Gemeinschaft auf das einzige Ḥarf der Quraiš vereinte, um Zwietracht zu verhindern. Ibn al-Ǧazarī, Abū Šāma und viele spätere Gelehrte meinten, die Exemplare enthielten, was von den Aḥruf bei der letzten Vorlage feststand, wobei der punktlose Rasm mehrere Lesarten zulasse."],
    ar: ["من الذي رأى أن المصاحف العثمانية حفظت حرفًا واحدًا من الأحرف السبعة ومن خالفه؟", ["رأى الطبري أن الأمة اجتمعت على حرف واحد، وخالفه ابن الجزري وكثيرون فرأوا أن المصاحف حفظت ما ثبت من الأحرف في العرضة الأخيرة", "رأى ابن الجزري أنه حرف واحد ورأى الطبري الأحرف كلها", "رأى أبو شامة أن المصاحف خلت من الأحرف السبعة", "رأى كلاهما أن الأحرف مكتوبة في المصاحف نصوصًا منفصلة"], "ذهب الطبري في مقدمة تفسيره إلى أن الإذن بالقراءة على سبعة أحرف كان رخصة انتهت حين جمع عثمان الأمة على حرف قريش واحد لدرء الفتنة، وذهب ابن الجزري وأبو شامة وكثير من المتأخرين إلى أن المصاحف تضم ما ثبت من الأحرف في العرضة الأخيرة، وأن الرسم الخالي من النقط يحتمل عدة قراءات."] },
];
